-- admin_list_guest_progress(text,text,text,text,boolean)  md5=d92e89cb1280767bb8cdeb0bd9a9f5c7
CREATE OR REPLACE FUNCTION public.admin_list_guest_progress(p_course_id text DEFAULT NULL::text, p_week_code text DEFAULT NULL::text, p_activity_type text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_completed boolean DEFAULT NULL::boolean)
 RETURNS TABLE(user_id uuid, email text, course_id text, week_code text, activity_key text, activity_type text, current_level integer, score smallint, completed boolean, updated_at timestamp with time zone, student_code text, class_code text, seat_no smallint, display_name text, identity_source text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    select
        null::uuid as user_id,
        null::text as email,
        gp.course_id,
        gp.week_code,
        gp.activity_key,
        case
            when gp.activity_key like 'typing%' then 'typing'
            when gp.activity_key like 'quiz%' or gp.activity_key like '%\_quiz\_%' escape '\' or gp.activity_key like '%\_quiz' escape '\' then 'quiz'
            when gp.activity_key like 'project%' then 'project'
            else 'other'
        end as activity_type,
        gp.current_level,
        gp.score,
        gp.completed,
        gp.updated_at,
        gp.student_code,
        gp.class_code,
        gp.seat_no,
        gp.display_name,
        'class-card'::text as identity_source
    from public.guest_progress gp
    where public.is_teacher()
      and (p_course_id is null or gp.course_id = p_course_id)
      and (p_week_code is null or gp.week_code = p_week_code)
      and (
            p_activity_type is null
            or case
                when gp.activity_key like 'typing%' then 'typing'
                when gp.activity_key like 'quiz%' or gp.activity_key like '%\_quiz\_%' escape '\' or gp.activity_key like '%\_quiz' escape '\' then 'quiz'
                when gp.activity_key like 'project%' then 'project'
                else 'other'
               end = p_activity_type
          )
      and (
            p_search is null
            or coalesce(gp.display_name, '') ilike '%' || p_search || '%'
            or coalesce(gp.student_code, '') ilike '%' || p_search || '%'
            or coalesce(gp.class_code, '') ilike '%' || p_search || '%'
            or gp.activity_key ilike '%' || p_search || '%'
          )
      and (p_completed is null or gp.completed = p_completed)
    order by gp.updated_at desc, gp.class_code asc, gp.seat_no asc, gp.activity_key asc;
$function$;
revoke all on function public.admin_list_guest_progress(text,text,text,text,boolean) from public, anon, authenticated, service_role;
grant execute on function public.admin_list_guest_progress(text,text,text,text,boolean) to public;
grant execute on function public.admin_list_guest_progress(text,text,text,text,boolean) to postgres;
grant execute on function public.admin_list_guest_progress(text,text,text,text,boolean) to anon;
grant execute on function public.admin_list_guest_progress(text,text,text,text,boolean) to authenticated;
grant execute on function public.admin_list_guest_progress(text,text,text,text,boolean) to service_role;

-- admin_list_progress(text,text,text,boolean)  md5=91676b748e9456d8201f0331780ba0e8
CREATE OR REPLACE FUNCTION public.admin_list_progress(p_week_code text DEFAULT NULL::text, p_activity_type text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_completed boolean DEFAULT NULL::boolean)
 RETURNS TABLE(user_id uuid, email text, week_code text, activity_key text, activity_type text, current_level integer, score smallint, completed boolean, updated_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    select
        sp.user_id,
        au.email::text,
        sp.week_code,
        sp.activity_key,
        case
            when sp.activity_key like 'typing%' then 'typing'
            when sp.activity_key like 'quiz%' then 'quiz'
            when sp.activity_key like 'project%' then 'project'
            else 'other'
        end as activity_type,
        sp.current_level,
        sp.score,
        sp.completed,
        sp.updated_at
    from public.student_progress sp
    join auth.users au on au.id = sp.user_id
    where public.is_teacher()
      and (p_week_code is null or sp.week_code = p_week_code)
      and (
            p_activity_type is null
            or case
                when sp.activity_key like 'typing%' then 'typing'
                when sp.activity_key like 'quiz%' then 'quiz'
                when sp.activity_key like 'project%' then 'project'
                else 'other'
               end = p_activity_type
          )
      and (
            p_search is null
            or au.email ilike '%' || p_search || '%'
            or sp.activity_key ilike '%' || p_search || '%'
          )
      and (p_completed is null or sp.completed = p_completed)
    order by sp.updated_at desc, au.email asc, sp.week_code asc, sp.activity_key asc;
$function$;
revoke all on function public.admin_list_progress(text,text,text,boolean) from public, anon, authenticated, service_role;
grant execute on function public.admin_list_progress(text,text,text,boolean) to public;
grant execute on function public.admin_list_progress(text,text,text,boolean) to postgres;
grant execute on function public.admin_list_progress(text,text,text,boolean) to anon;
grant execute on function public.admin_list_progress(text,text,text,boolean) to authenticated;
grant execute on function public.admin_list_progress(text,text,text,boolean) to service_role;

