-- admin_list_student_enrollments(smallint)  md5=7cace1115a8da7a8648ed55f59f9abf1
CREATE OR REPLACE FUNCTION public.admin_list_student_enrollments(p_school_year smallint)
 RETURNS TABLE(school_year smallint, user_id uuid, email text, class_code text, seat_no smallint, display_name text, student_code text, role text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    select e.school_year, u.id, e.email, e.class_code, e.seat_no, e.display_name,
           e.class_code || lpad(e.seat_no::text, 2, '0'), 'student'::text
    from public.student_enrollments e
    left join auth.users u on lower(u.email) = e.email
    where public.is_teacher() and e.school_year = p_school_year
    order by e.class_code, e.seat_no, e.email;
$function$;
revoke all on function public.admin_list_student_enrollments(smallint) from public, anon, authenticated, service_role;
grant execute on function public.admin_list_student_enrollments(smallint) to postgres;
grant execute on function public.admin_list_student_enrollments(smallint) to authenticated;
