-- admin_list_student_profiles(text,text)  md5=ee24d2bdde9a8a140deb9fc4fe5488a2
CREATE OR REPLACE FUNCTION public.admin_list_student_profiles(p_class_code text DEFAULT NULL::text, p_search text DEFAULT NULL::text)
 RETURNS TABLE(user_id uuid, email text, class_code text, seat_no smallint, display_name text, student_code text, role text, updated_at timestamp with time zone)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
    select
        prof.user_id,
        coalesce(prof.email, au.email::text) as email,
        prof.class_code,
        prof.seat_no,
        prof.display_name,
        prof.student_code,
        prof.role,
        prof.updated_at
    from public.student_profiles prof
    left join auth.users au on au.id = prof.user_id
    where public.is_teacher()
      and (p_class_code is null or prof.class_code = p_class_code)
      and (
            p_search is null
            or coalesce(prof.email, au.email::text) ilike '%' || p_search || '%'
            or coalesce(prof.display_name, '') ilike '%' || p_search || '%'
            or coalesce(prof.student_code, '') ilike '%' || p_search || '%'
          )
    order by prof.class_code asc nulls last, prof.seat_no asc nulls last, prof.display_name asc nulls last;
$function$;
revoke all on function public.admin_list_student_profiles(text,text) from public, anon, authenticated, service_role;
grant execute on function public.admin_list_student_profiles(text,text) to public;
grant execute on function public.admin_list_student_profiles(text,text) to postgres;
grant execute on function public.admin_list_student_profiles(text,text) to anon;
grant execute on function public.admin_list_student_profiles(text,text) to authenticated;
grant execute on function public.admin_list_student_profiles(text,text) to service_role;

