-- admin_set_classroom_control(text,text,text,boolean)  md5=fd502384a7ac0cfff50e77c5d2f3307b
CREATE OR REPLACE FUNCTION public.admin_set_classroom_control(p_grade text, p_week_code text, p_control_key text, p_is_enabled boolean)
 RETURNS TABLE(grade text, week_code text, control_key text, is_enabled boolean, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
    if not public.is_teacher() then
        raise exception 'not authorized';
    end if;

    insert into public.classroom_controls (
        grade,
        week_code,
        control_key,
        is_enabled,
        updated_by,
        updated_at
    )
    values (
        p_grade,
        p_week_code,
        p_control_key,
        p_is_enabled,
        auth.uid(),
        now()
    )
    on conflict on constraint classroom_controls_pkey
    do update set
        is_enabled = excluded.is_enabled,
        updated_by = auth.uid(),
        updated_at = now();

    return query
    select
        cc.grade,
        cc.week_code,
        cc.control_key,
        cc.is_enabled,
        cc.updated_at
    from public.classroom_controls cc
    where cc.grade = p_grade
        and cc.week_code = p_week_code
        and cc.control_key = p_control_key;
end;
$function$;
revoke all on function public.admin_set_classroom_control(text,text,text,boolean) from public, anon, authenticated, service_role;
grant execute on function public.admin_set_classroom_control(text,text,text,boolean) to public;
grant execute on function public.admin_set_classroom_control(text,text,text,boolean) to postgres;
grant execute on function public.admin_set_classroom_control(text,text,text,boolean) to anon;
