-- drive_begin_oauth(uuid,text,text)  md5=f3984b4ddc8045eb5c73b6d4f1a08b03
CREATE OR REPLACE FUNCTION public.drive_begin_oauth(p_user_id uuid, p_state_hash text, p_proof_hash text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                    begin
                      if length(p_state_hash) <> 43 or length(p_proof_hash) <> 43 then
                          raise exception 'invalid oauth state';
                            end if;
                              delete from public.drive_oauth_states where expires_at <= now();
                                insert into public.drive_oauth_states (owner_user_id, state_hash, proof_hash, expires_at)
                                  values (p_user_id, p_state_hash, p_proof_hash, now() + interval '10 minutes')
                                    on conflict (owner_user_id) do update set
                                        state_hash = excluded.state_hash, proof_hash = excluded.proof_hash, expires_at = excluded.expires_at;
                                        end;
                                        $function$;
revoke all on function public.drive_begin_oauth(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function public.drive_begin_oauth(uuid,text,text) to postgres;
grant execute on function public.drive_begin_oauth(uuid,text,text) to service_role;

-- drive_claim_oauth(uuid,text,text)  md5=7b8ea4e18b874fcbf9503ab7ebebe5bf
CREATE OR REPLACE FUNCTION public.drive_claim_oauth(p_user_id uuid, p_state_hash text, p_proof_hash text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
                                        declare claimed uuid;
                                        begin
                                          delete from public.drive_oauth_states
                                            where owner_user_id = p_user_id and state_hash = p_state_hash and proof_hash = p_proof_hash
                                                and expires_at > now()
                                                  returning owner_user_id into claimed;
                                                    return claimed is not null;
                                                    end;
                                                    $function$;
revoke all on function public.drive_claim_oauth(uuid,text,text) from public, anon, authenticated, service_role;
grant execute on function public.drive_claim_oauth(uuid,text,text) to postgres;
grant execute on function public.drive_claim_oauth(uuid,text,text) to service_role;

-- foundation_milestone_rewards(text,jsonb)  md5=575c1ad4d71a8cec1f5a90730b4df9ed
CREATE OR REPLACE FUNCTION public.foundation_milestone_rewards(p_course_id text, p_rows jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 with records as (
  select distinct on (value->>'lesson_key') value r from jsonb_array_elements(coalesce(p_rows,'[]')) with ordinality order by value->>'lesson_key',ordinality desc
 ), earned as (
  select d.*,case when count(coalesce(nullif(r.r->>'completed_at',''),nullif(r.r->>'updated_at','')))=cardinality(d.lesson_keys)
   then max(coalesce(nullif(r.r->>'completed_at',''),nullif(r.r->>'updated_at',''))::timestamptz) end earned_at
  from public.foundation_milestone_definitions d cross join lateral unnest(d.lesson_keys) k(key)
  left join records r on r.r->>'lesson_key'=k.key
  where p_course_id in ('grade3-115-1','grade6-115-1')
  group by d.milestone_key
  having bool_and(coalesce(r.r->'completed'='true'::jsonb,false)) and bool_and(exists(select 1 from public.garden_reward_catalog c where c.course_id=p_course_id and c.week_code='foundation' and c.kind='foundation' and c.activity_key=k.key))
 ) select coalesce(jsonb_agg(jsonb_build_object('id',p_course_id||':foundation:'||milestone_key||':flower:1','kind','flower','sourceType','foundation','track',track,'earnedAt',earned_at) order by track,ordinal),'[]'::jsonb) from earned;
$function$;
revoke all on function public.foundation_milestone_rewards(text,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.foundation_milestone_rewards(text,jsonb) to postgres;
grant execute on function public.foundation_milestone_rewards(text,jsonb) to service_role;

-- partner_pilot.freeze_allocation()  md5=709976471cb502ce109f344030fefcad
CREATE OR REPLACE FUNCTION partner_pilot.freeze_allocation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare roster uuid[]; loads integer[]; pack record; pos integer; n integer;
begin
 if TG_OP='INSERT' then
  if new.started then raise exception 'ALLOCATION_INVALID_STATE';end if;
  new.allocation_version:=case when (select past_meta is not null from partner_pilot.papers where id=new.paper) then 1 else 0 end;
  if new.allocation_version=1 then perform * from partner_pilot.allocation_items(new.paper);end if;
  return new;
 end if;
 if new.allocation_version is distinct from old.allocation_version or
  (old.started and (not new.started or new.paper<>old.paper or new.capacity<>old.capacity)) then raise exception 'ALLOCATION_FROZEN';end if;
 if not old.started and new.started and new.allocation_version=1 then
  select array_agg(user_id order by joined_at,user_id) into roster from partner_pilot.members where room_id=new.id;
  if cardinality(roster) is distinct from new.capacity then raise exception 'NOT_READY';end if;
  if exists(select 1 from partner_pilot.allocations where room_id=new.id) then raise exception 'ALLOCATION_FROZEN';end if;
  select count(distinct unit_id) into n from partner_pilot.allocation_items(new.paper);
  if n<new.capacity then raise exception 'ALLOCATION_TOO_FEW_UNITS';end if;
  loads:=array_fill(0,array[new.capacity]);
  -- Deterministic largest-pack-first scheduling. Bounded O(items * members), no search explosion.
  for pack in select unit_id,max(weight) weight,array_agg(qid order by qid) qids
    from partner_pilot.allocation_items(new.paper) group by unit_id order by max(weight) desc,unit_id collate "C" loop
   select i into pos from generate_subscripts(loads,1) i order by loads[i],i limit 1;
   insert into partner_pilot.allocations(room_id,qid,user_id,unit_id)
    select new.id,q,roster[pos],pack.unit_id from unnest(pack.qids) q;
   loads[pos]:=loads[pos]+pack.weight;
  end loop;
  if exists(select 1 from unnest(loads) v where v=0) then raise exception 'ALLOCATION_TOO_FEW_UNITS';end if;
 end if;
 return new;
end $function$;
revoke all on function partner_pilot.freeze_allocation() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.freeze_allocation() to postgres;

-- freeze_grade3_guest_progress()  md5=3b288a1b4339c370c540200cc6ddb251
