 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if (tg_op<>'DELETE' and new.course_id='grade3-115-1') or (tg_op<>'INSERT' and old.course_id='grade3-115-1') then
   raise exception '本課程已切換 Google 登入，歷史成果已凍結，請重新整理並登入。';
 end if;
