-- garden_pet_visit(text)  md5=ce37d2a123b6563b7fad3c18190126d2
CREATE OR REPLACE FUNCTION public.garden_pet_visit(p_course_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();t timestamptz;v public.garden_pet_visits;chosen public.garden_companion_choices;
 eligible boolean;won boolean:=false;rapid boolean:=false;
begin
 if uid is null then raise exception 'authentication_required';end if;
 if p_course_id is null or p_course_id not in('grade3-114-2','grade3-115-1','grade4-115-1','grade6-115-1','grade9-115-1') then raise exception 'invalid_request';end if;
 if coalesce(public.is_teacher(),false) or not exists(
  select 1 from auth.users u join public.student_enrollments e on e.email=lower(u.email)
  where u.id=uid and u.email_confirmed_at is not null and e.school_year=115
  and left(e.class_code,1)=substring(p_course_id from 6 for 1)
 ) then raise exception 'student_required';end if;
 -- Same lock as the preference RPC: simultaneous tabs cannot each draw.
 perform pg_advisory_xact_lock(hashtextextended('garden-choices:'||uid::text,0));
 select * into chosen from public.garden_companion_choices where user_id=uid;
 if coalesce(chosen.modes->>chosen.pet,'walk')<>'rest'
  or not exists(select 1 from public.garden_growth where user_id=uid and course_id=p_course_id)
  or not exists(select 1 from public.garden_item_unlocks where user_id=uid and item_key='pet:'||chosen.pet)
 then return jsonb_build_object('surprise',false,'refreshMessage',false);end if;
 t:=clock_timestamp();
 select * into v from public.garden_pet_visits where user_id=uid;
 eligible:=v.user_id is null or t>=v.next_roll_at;
 if eligible then
  won:=random()<0.2;
  insert into public.garden_pet_visits(user_id,next_roll_at,refresh_window_at,refresh_count)
   values(uid,t+interval '5 minutes',t,1)
   on conflict(user_id) do update set next_roll_at=excluded.next_roll_at,refresh_window_at=t,refresh_count=1
   returning * into v;
 else
  if t>=v.refresh_window_at+interval '1 minute' then v.refresh_window_at:=t;v.refresh_count:=1;
  else v.refresh_count:=least(1000,v.refresh_count+1);end if;
  rapid:=v.refresh_count>=3;
  update public.garden_pet_visits set refresh_window_at=v.refresh_window_at,refresh_count=v.refresh_count where user_id=uid;
 end if;
 return jsonb_build_object('surprise',won,'refreshMessage',rapid,'cooldownUntil',v.next_roll_at);
end$function$;
revoke all on function public.garden_pet_visit(text) from public, anon, authenticated, service_role;
grant execute on function public.garden_pet_visit(text) to postgres;
grant execute on function public.garden_pet_visit(text) to authenticated;
grant execute on function public.garden_pet_visit(text) to service_role;

-- garden_quiz_leaf_map(jsonb,text)  md5=980ab586bf5cd0c0a183be552c17c58e
CREATE OR REPLACE FUNCTION public.garden_quiz_leaf_map(awards jsonb, course text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare a jsonb;pending text;awid text;units int;i int;key text;rid text;result jsonb:='[]';
begin
 for a in select value from jsonb_array_elements(coalesce(awards,'[]')) loop
  awid:=a->>'id';units:=coalesce((a->>'half_units')::int,2);
  if awid is null or units not between 1 and 2000 then raise exception 'invalid_reward';end if;
  for i in 0..units-1 loop
   key:=awid||':'||i;
   if pending is null then pending:=key;
   else
    rid:=case when pending=awid||':0' and i=1 and units=2 then awid else 'pair:'||pending||':'||key end;
    result:=result||jsonb_build_array(jsonb_build_object('id',course||':00:practice_'||rid||':quiz-leaf:1','kind','quiz-leaf','halves',jsonb_build_array(pending,key)));
    pending:=null;
   end if;
  end loop;
 end loop;
 return result;
end$function$;
revoke all on function public.garden_quiz_leaf_map(jsonb,text) from public, anon, authenticated, service_role;
grant execute on function public.garden_quiz_leaf_map(jsonb,text) to postgres;
grant execute on function public.garden_quiz_leaf_map(jsonb,text) to service_role;

-- garden_test_rewards(text)  md5=abf6f06d50bc2a01c250b0f5b37152b0
CREATE OR REPLACE FUNCTION public.garden_test_rewards(p_course_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',t.course_id||':test-setup:'||t.setup_id::text||':'||x.kind||':'||x.i,
  'kind',x.kind,'earned',true,'courseId',t.course_id,'weekCode','test',
  'activityKey','garden-upgrade-rehearsal','label',U&'\6210\9577\9AD4\9A57\6E96\5099',
  'title',U&'\6210\9577\9AD4\9A57\6E96\5099\30FB'||case when x.kind='flower' then U&'\82B1\6735' else U&'\8449\7247' end||' '||x.i,
  'reason',U&'\8001\5E2B\6E2C\8A66\5E33\865F\7684\5347\7D1A\9AD4\9A57\6E96\5099\3002',
  'detail',U&'\7368\7ACB\6E2C\8A66\8CC7\6599\FF0C\4E0D\4EE3\8868\5B8C\6210\8AB2\7A0B\6216\6E2C\9A57\3002',
  'href',''
 ) order by x.kind,x.i),'[]'::jsonb)
 from public.garden_test_setup t join auth.users u on u.id=t.user_id
 cross join lateral (
  select 'typing-leaf'::text kind,i from generate_series(1,t.leaves)i
  union all select 'flower',i from generate_series(1,t.flowers)i
 ) x
 where t.user_id=auth.uid() and t.course_id=p_course_id and u.email_confirmed_at is not null
 and lower(u.email)='chianwu@apps.ntpc.edu.tw'
 and exists(select 1 from public.student_enrollments e where e.school_year=115 and e.email=lower(u.email) and e.class_code='307' and e.seat_no=30)
$function$;
revoke all on function public.garden_test_rewards(text) from public, anon, authenticated, service_role;
grant execute on function public.garden_test_rewards(text) to postgres;
grant execute on function public.garden_test_rewards(text) to authenticated;
grant execute on function public.garden_test_rewards(text) to service_role;

-- garden_tree_skin(text)  md5=7b81621076704c5b43b95b7000a6fdc3
CREATE OR REPLACE FUNCTION public.garden_tree_skin(p_skin text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); chosen text;
begin
 if uid is null then raise exception 'authentication_required';end if;
 if coalesce(public.is_teacher(),false) or not exists(
  select 1 from auth.users u join public.student_enrollments e on e.email=lower(u.email)
  where u.id=uid and u.email_confirmed_at is not null and e.school_year=115 and left(e.class_code,1) in('3','6')
 ) then raise exception 'student_required';end if;
 if not exists(select 1 from public.garden_growth where user_id=uid) then raise exception 'level_two_required';end if;
 if p_skin is not null then
  if p_skin not in('a','b') then raise exception 'invalid_skin';end if;
  insert into public.garden_tree_skins(user_id,skin) values(uid,p_skin)
   on conflict(user_id) do update set skin=excluded.skin,updated_at=now()
   where garden_tree_skins.skin is distinct from excluded.skin;
 end if;
 select skin into chosen from public.garden_tree_skins where user_id=uid;
 return jsonb_build_object('skin',coalesce(chosen,'a'));
end$function$;
revoke all on function public.garden_tree_skin(text) from public, anon, authenticated, service_role;
grant execute on function public.garden_tree_skin(text) to postgres;
grant execute on function public.garden_tree_skin(text) to authenticated;
grant execute on function public.garden_tree_skin(text) to service_role;

-- garden_unlock_items(text,integer,integer)  md5=6b1cb17d5f318a82ae840baad3d93c6a
CREATE OR REPLACE FUNCTION public.garden_unlock_items(course text, new_leaves integer, new_flowers integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();c record;added text;owned jsonb;
begin
 for c in select * from public.garden_item_catalog() order by leaves,item_key loop
  if new_leaves>=c.leaves or new_flowers>=c.flowers then
   added:=null;
   insert into public.garden_item_unlocks(user_id,item_key,course_id) values(uid,c.item_key,course)
    on conflict do nothing returning item_key into added;
   if added is not null then insert into public.garden_item_notices(user_id,item_key,course_id) values(uid,added,course) on conflict do nothing;end if;
  end if;
 end loop;
 select coalesce(jsonb_agg(item_key order by item_key),'[]') into owned from public.garden_item_unlocks where user_id=uid;
 return owned;
end$function$;
revoke all on function public.garden_unlock_items(text,integer,integer) from public, anon, authenticated, service_role;
grant execute on function public.garden_unlock_items(text,integer,integer) to postgres;
grant execute on function public.garden_unlock_items(text,integer,integer) to service_role;

-- garden_unlock_notice(text,text,uuid)  md5=442fa444b9a9471aa8a555fbc859d05a
CREATE OR REPLACE FUNCTION public.garden_unlock_notice(p_course_id text DEFAULT NULL::text, p_action text DEFAULT 'pending'::text, p_claim uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();course text;claim uuid;items jsonb;g jsonb;
begin
 if uid is null then raise exception 'authentication_required';end if;
 if coalesce(public.is_teacher(),false) or not exists(select 1 from auth.users u join public.student_enrollments e on e.email=lower(u.email)
  where u.id=uid and u.email_confirmed_at is not null and e.school_year=115 and left(e.class_code,1) in('3','6')) then raise exception 'student_required';end if;
 if p_action is null or p_action not in('check','pending','claim','ack') then raise exception 'invalid_action';end if;
 if p_action in('check','ack') and (p_course_id is null or p_course_id not in('grade3-114-2','grade3-115-1','grade4-115-1','grade6-115-1','grade9-115-1')) then raise exception 'invalid_course';end if;
 perform pg_advisory_xact_lock(hashtextextended('garden-notices:'||uid::text,0));
 if p_action='check' then
  -- Existing grown records only: never take a surprise baseline before the
  -- student's first visit to their newly grown tree.
  if exists(select 1 from public.garden_growth where user_id=uid and course_id=p_course_id) then g:=public.garden_growth(p_course_id,'get');end if;
 elsif p_action='ack' then
  update public.garden_item_notices set seen_at=now(),claim_until=null
   where user_id=uid and course_id=p_course_id and seen_at is null and claim_id=p_claim;
  return null;
 end if;
 if p_action='claim' and exists(select 1 from public.garden_item_notices where user_id=uid and seen_at is null and claim_until>now()) then return null;end if;
 select course_id into course from public.garden_item_notices where user_id=uid and seen_at is null order by created_at,item_key limit 1;
 if course is null then return null;end if;
 if p_action='claim' then
  claim:=gen_random_uuid();
  update public.garden_item_notices set claim_id=claim,claim_until=now()+interval '2 minutes' where user_id=uid and course_id=course and seen_at is null;
 end if;
 select jsonb_agg(jsonb_build_object('key',c.item_key,'label',c.label,'portrait',c.portrait) order by c.leaves,c.item_key) into items
 from public.garden_item_notices n join public.garden_item_catalog() c on c.item_key=n.item_key where n.user_id=uid and n.course_id=course and n.seen_at is null
 and (p_action<>'claim' or n.claim_id=claim);
 return jsonb_build_object('courseId',course,'claim',claim,'items',items);
end$function$;
revoke all on function public.garden_unlock_notice(text,text,uuid) from public, anon, authenticated, service_role;
grant execute on function public.garden_unlock_notice(text,text,uuid) to postgres;
grant execute on function public.garden_unlock_notice(text,text,uuid) to authenticated;
grant execute on function public.garden_unlock_notice(text,text,uuid) to service_role;

