-- partner_pilot.guard_allocation_source()  md5=856e7171a70e546c0ec7c67890bc35e5
CREATE OR REPLACE FUNCTION partner_pilot.guard_allocation_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare pid text; frozen boolean;
begin
 if TG_TABLE_NAME='papers' then
  if TG_OP='UPDATE' and (new.source_version,new.source_sha,new.total,new.past_meta,new.content_key)
   is not distinct from (old.source_version,old.source_sha,old.total,old.past_meta,old.content_key) then return new;end if;
  pid:=old.id;
 elsif TG_TABLE_NAME='paper_items' then
  if TG_OP<>'INSERT' and exists(select 1 from partner_pilot.rooms where paper=old.paper_id and allocation_version=1) then raise exception 'ALLOCATION_SOURCE_FROZEN';end if;
  if TG_OP<>'DELETE' then pid:=new.paper_id;end if;
 else
  select exists(select 1 from partner_pilot.paper_items i join partner_pilot.rooms r on r.paper=i.paper_id
   where i.qid=old.id and r.allocation_version=1) into frozen;
  if frozen then raise exception 'ALLOCATION_SOURCE_FROZEN';end if;
 end if;
 if pid is not null and exists(select 1 from partner_pilot.rooms where paper=pid and allocation_version=1) then raise exception 'ALLOCATION_SOURCE_FROZEN';end if;
 if TG_OP='DELETE' then return old;else return new;end if;
end $function$;
revoke all on function partner_pilot.guard_allocation_source() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.guard_allocation_source() to postgres;

-- homework_action(text,jsonb)  md5=abfe6f270daa5356642b35c09788c573
CREATE OR REPLACE FUNCTION public.homework_action(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
 uid uuid:=auth.uid(); teacher boolean:=coalesce(public.is_teacher(),false);
 v_email text; cls text; a public.homework_assignments; s public.homework_submissions; result jsonb;
begin
 if uid is null then raise exception 'login_required'; end if;
 select lower(u.email) into v_email from auth.users u where u.id=uid and u.email_confirmed_at is not null;
 if v_email is null then raise exception 'login_required'; end if;
 select e.class_code into cls from public.student_enrollments e where e.school_year=115 and e.email=v_email and e.class_code like '6%';
 if p_action='list' then
   if not teacher and cls is null then raise exception 'roster_required'; end if;
   select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'title',a.title,'instructions',a.instructions,
     'week_code',a.week_code,'class_code',a.class_code,'state',a.state,'course_id',a.course_id,
     'submission',(select jsonb_build_object('upload_id',s.upload_id,'status',s.status,'feedback',s.feedback,
       'submitted_at',s.submitted_at,'reviewed_at',s.reviewed_at,'file_name',u.file_name)
       from public.homework_submissions s join public.homework_uploads u on u.id=s.upload_id where s.assignment_id=a.id and s.user_id=uid)
     ) order by a.week_code,a.created_at),'[]') into result
   from public.homework_assignments a where (teacher and a.owner_user_id=uid) or
     (not teacher and a.state<>'draft' and a.class_code in ('*',cls));
   return jsonb_build_object('assignments',result,'teacher',teacher,'class_code',cls,'max_file_bytes',(select max_file_bytes from public.homework_settings where id));
 end if;
 if p_action='create' then
   if not teacher then raise exception 'teacher_required'; end if;
   if not exists(select 1 from public.drive_connections where owner_user_id=uid) then raise exception 'drive_required'; end if;
   insert into public.homework_assignments(owner_user_id,week_code,title,instructions,class_code)
     values(uid,p_data->>'week_code',trim(p_data->>'title'),coalesce(p_data->>'instructions',''),p_data->>'class_code') returning * into a;
   return to_jsonb(a);
 end if;
 select * into a from public.homework_assignments where id=(p_data->>'assignment_id')::uuid for update;
 if a.id is null then raise exception 'assignment_unavailable'; end if;
 if p_action='upload_context' then
   if cls is null or a.class_code not in ('*',cls) or a.state<>'open' or a.drive_folder_id is null then raise exception 'assignment_unavailable'; end if;
   return to_jsonb(a) || jsonb_build_object('max_file_bytes',(select max_file_bytes from public.homework_settings where id));
 end if;
 if not teacher or a.owner_user_id<>uid then raise exception 'teacher_required'; end if;
 if p_action='context' then return to_jsonb(a); end if;
 if p_action='set_state' then
   if p_data->>'state' not in ('open','closed') or (p_data->>'state'='open' and a.drive_folder_id is null) then raise exception 'invalid_state'; end if;
   update public.homework_assignments set state=p_data->>'state' where id=a.id;
   return jsonb_build_object('ok',true);
 end if;
 if p_action='roster' then
   select coalesce(jsonb_agg(jsonb_build_object('email',e.email,'class_code',e.class_code,'seat_no',e.seat_no,'display_name',e.display_name,
     'user_id',u.id,'status',coalesce(s.status,'missing'),'upload_id',s.upload_id,'feedback',s.feedback,
     'submitted_at',s.submitted_at,'file_name',f.file_name,'drive_file_id',f.drive_file_id)
     order by e.class_code,e.seat_no),'[]') into result
   from public.student_enrollments e left join auth.users u on lower(u.email)=e.email
   left join public.homework_submissions s on s.user_id=u.id and s.assignment_id=a.id
   left join public.homework_uploads f on f.id=s.upload_id
   where e.school_year=115 and e.class_code like '6%' and a.class_code in ('*',e.class_code);
   return jsonb_build_object('assignment',to_jsonb(a),'students',result);
 end if;
 if p_action='review' then
   if p_data->>'status' not in ('passed','needs_revision') or length(coalesce(p_data->>'feedback',''))>2000 then raise exception 'invalid_review'; end if;
   select * into s from public.homework_submissions where assignment_id=a.id and user_id=(p_data->>'user_id')::uuid for update;
   if s.upload_id is null or s.upload_id is distinct from (p_data->>'upload_id')::uuid then raise exception 'version_changed'; end if;
   if s.status=p_data->>'status' and s.feedback=coalesce(p_data->>'feedback','') then return jsonb_build_object('ok',true); end if;
   update public.homework_submissions set status=p_data->>'status',feedback=coalesce(p_data->>'feedback',''),reviewed_at=now()
     where assignment_id=a.id and user_id=s.user_id;
   insert into public.homework_events(assignment_id,user_id,upload_id,actor_id,event,feedback)
     values(a.id,s.user_id,s.upload_id,uid,p_data->>'status',coalesce(p_data->>'feedback',''));
   return jsonb_build_object('ok',true);
 end if;
 raise exception 'invalid_action';
end $function$;
revoke all on function public.homework_action(text,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.homework_action(text,jsonb) to postgres;
grant execute on function public.homework_action(text,jsonb) to authenticated;
grant execute on function public.homework_action(text,jsonb) to service_role;

-- homework_finalize(uuid,uuid)  md5=bc701d692d55c06d0469cb9522094c85
CREATE OR REPLACE FUNCTION public.homework_finalize(p_user uuid, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u public.homework_uploads; a public.homework_assignments; cls text;
begin
 select * into u from public.homework_uploads where id=p_id and user_id=p_user;
 if u.id is null then raise exception 'upload_unavailable'; end if;
 select * into a from public.homework_assignments where id=u.assignment_id for update;
 select * into u from public.homework_uploads where id=p_id for update;
 if u.submitted_at is not null then return jsonb_build_object('ok',true); end if;
 select e.class_code into cls from public.student_enrollments e join auth.users x on lower(x.email)=e.email
   where x.id=p_user and e.school_year=115 and e.class_code like '6%';
 if cls is null or a.class_code not in ('*',cls) or a.state<>'open' or u.expires_at<=now() then raise exception 'upload_expired'; end if;
 update public.homework_uploads set submitted_at=now() where id=p_id;
 insert into public.homework_submissions(assignment_id,user_id,upload_id,status,submitted_at)
   values(u.assignment_id,p_user,p_id,'submitted',now()) on conflict(assignment_id,user_id)
   do update set upload_id=excluded.upload_id,status='submitted',feedback='',submitted_at=excluded.submitted_at,reviewed_at=null;
 insert into public.homework_events(assignment_id,user_id,upload_id,actor_id,event) values(u.assignment_id,p_user,p_id,p_user,'submitted');
 return jsonb_build_object('ok',true);
end $function$;
revoke all on function public.homework_finalize(uuid,uuid) from public, anon, authenticated, service_role;
grant execute on function public.homework_finalize(uuid,uuid) to postgres;
grant execute on function public.homework_finalize(uuid,uuid) to service_role;

-- homework_reserve(uuid,uuid,uuid,text,text,integer,text)  md5=0f4397a887fbda587b363bd0b014e2f0
CREATE OR REPLACE FUNCTION public.homework_reserve(p_user uuid, p_assignment uuid, p_id uuid, p_drive_id text, p_name text, p_size integer, p_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a public.homework_assignments; u public.homework_uploads; cls text;
begin
 if p_size>(select max_file_bytes from public.homework_settings where id) then raise exception 'file_size'; end if;
 select * into a from public.homework_assignments where id=p_assignment for update;
 select e.class_code into cls from public.student_enrollments e join auth.users x on lower(x.email)=e.email
   where x.id=p_user and x.email_confirmed_at is not null and e.school_year=115 and e.class_code like '6%';
 if cls is null or a.id is null or a.state<>'open' or a.drive_folder_id is null or a.class_code not in ('*',cls) then raise exception 'assignment_unavailable'; end if;
 select * into u from public.homework_uploads where id=p_id;
 if u.id is not null then
   if u.user_id<>p_user or u.assignment_id<>p_assignment or u.sha256<>p_sha256 or u.file_name<>p_name or u.file_size<>p_size then raise exception 'upload_conflict'; end if;
   return to_jsonb(u);
 end if;
 -- A new attempt explicitly replaces any unfinished attempt for this assignment.
 update public.homework_uploads set expires_at=now() where assignment_id=p_assignment and user_id=p_user and submitted_at is null and expires_at>now();
 if (select count(*) from public.homework_uploads where assignment_id=p_assignment and user_id=p_user and created_at>now()-interval '1 hour')>=10 then raise exception 'upload_limit'; end if;
 insert into public.homework_uploads(id,assignment_id,user_id,drive_file_id,file_name,file_size,sha256)
   values(p_id,p_assignment,p_user,p_drive_id,p_name,p_size,p_sha256) returning * into u;
 return to_jsonb(u);
end $function$;
revoke all on function public.homework_reserve(uuid,uuid,uuid,text,text,integer,text) from public, anon, authenticated, service_role;
grant execute on function public.homework_reserve(uuid,uuid,uuid,text,text,integer,text) to postgres;
grant execute on function public.homework_reserve(uuid,uuid,uuid,text,text,integer,text) to service_role;

-- homework_review(text,jsonb)  md5=d37028e1005a15bdebc20f5862034f94
CREATE OR REPLACE FUNCTION public.homework_review(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 uid uuid:=auth.uid(); teacher boolean:=coalesce(public.is_teacher(),false);
 a public.homework_assignments; u public.homework_uploads; s public.homework_submissions;
 target uuid; cls text; result jsonb; lines jsonb; line jsonb; pt jsonb;
 v_feedback text; newstatus text;
begin
 if uid is null or not exists(select 1 from auth.users where id=uid and email_confirmed_at is not null) then raise exception 'login_required'; end if;
 select * into a from public.homework_assignments where id=(p_data->>'assignment_id')::uuid for update;
 if a.id is null then raise exception 'assignment_unavailable'; end if;
 if teacher then
  if a.owner_user_id<>uid then raise exception 'teacher_required'; end if;
  target:=(p_data->>'user_id')::uuid;
 else
  target:=uid;
  if p_data ? 'user_id' and (p_data->>'user_id')::uuid<>uid then raise exception 'teacher_required'; end if;
  select e.class_code into cls from public.student_enrollments e join auth.users x on lower(x.email)=e.email where x.id=uid and e.school_year=115;
  if cls is null or cls not like '6%' or a.class_code not in ('*',cls) or a.state='draft' then raise exception 'assignment_unavailable'; end if;
 end if;
 if p_action='history' then
  select coalesce(jsonb_agg(v order by v->>'submitted_at',v->>'id'),'[]') into result from (
   select jsonb_build_object('id',f.id,'file_name',f.file_name,'file_size',f.file_size,'submitted_at',f.submitted_at,
    'latest',f.id=sub.upload_id,'status',case when f.id=sub.upload_id then sub.status else coalesce(ev.event,'submitted') end,
    'feedback',coalesce(an.feedback,case when f.id=sub.upload_id then sub.feedback else ev.feedback end,''),
    'strokes',coalesce(an.strokes,'[]'::jsonb),'annotation_updated_at',an.updated_at) v
   from public.homework_uploads f
   left join public.homework_submissions sub on sub.assignment_id=f.assignment_id and sub.user_id=f.user_id
   left join public.homework_annotations an on an.upload_id=f.id
   left join lateral (select event,feedback from public.homework_events e where e.upload_id=f.id order by e.id desc limit 1) ev on true
   where f.assignment_id=a.id and f.user_id=target and f.submitted_at is not null
  ) rows;
  return jsonb_build_object('versions',result,'teacher',teacher);
 end if;
 select * into u from public.homework_uploads where id=(p_data->>'upload_id')::uuid and assignment_id=a.id and submitted_at is not null;
 if u.id is null or (not teacher and u.user_id<>uid) then raise exception 'assignment_unavailable'; end if;
 if p_action='media_context' then
  return jsonb_build_object('owner_user_id',a.owner_user_id,'drive_file_id',u.drive_file_id,'file_name',u.file_name,'file_size',u.file_size);
 end if;
 if p_action<>'save' or not teacher then raise exception 'teacher_required'; end if;
 select * into s from public.homework_submissions where assignment_id=a.id and user_id=u.user_id for update;
 if s.upload_id is distinct from u.id then raise exception 'version_changed'; end if;
 if p_data ? 'feedback' or p_data ? 'strokes' then
  -- Optimistic lock prevents another tab from silently overwriting a saved annotation.
  if (select updated_at from public.homework_annotations where upload_id=u.id) is distinct from (p_data->>'annotation_updated_at')::timestamptz then raise exception 'version_changed'; end if;
  v_feedback:=coalesce(p_data->>'feedback',s.feedback);lines:=coalesce(p_data->'strokes','[]'::jsonb);
  if length(v_feedback)>2000 or jsonb_typeof(lines)<>'array' or octet_length(lines::text)>250000 then raise exception 'invalid_review'; end if;
  if jsonb_array_length(lines)>300 then raise exception 'invalid_review'; end if;
  for line in select value from jsonb_array_elements(lines) loop
   if coalesce(line->>'color','') !~ '^#[0-9a-fA-F]{6}$' or jsonb_typeof(line->'width') is distinct from 'number' or (line->>'width')::numeric not between 0.001 and 0.03 or jsonb_typeof(line->'points') is distinct from 'array' then raise exception 'invalid_review'; end if;
   if jsonb_array_length(line->'points') not between 1 and 4000 then raise exception 'invalid_review'; end if;
   for pt in select value from jsonb_array_elements(line->'points') loop
    if jsonb_typeof(pt)<>'array' then raise exception 'invalid_review'; end if;
    if jsonb_array_length(pt)<>2 or jsonb_typeof(pt->0)<>'number' or jsonb_typeof(pt->1)<>'number' or (pt->>0)::numeric not between 0 and 1 or (pt->>1)::numeric not between 0 and 1 then raise exception 'invalid_review'; end if;
   end loop;
  end loop;
  insert into public.homework_annotations(upload_id,strokes,feedback) values(u.id,lines,v_feedback)
   on conflict(upload_id) do update set strokes=excluded.strokes,feedback=excluded.feedback,updated_at=clock_timestamp();
  update public.homework_submissions set feedback=v_feedback where assignment_id=a.id and user_id=u.user_id;
 end if;
 if p_data ? 'status' then
  newstatus:=p_data->>'status';
  if newstatus not in ('submitted','passed','needs_revision') then raise exception 'invalid_review'; end if;
  if s.status<>newstatus then
   update public.homework_submissions set status=newstatus,reviewed_at=case when newstatus='submitted' then null else now() end where assignment_id=a.id and user_id=u.user_id;
   insert into public.homework_events(assignment_id,user_id,upload_id,actor_id,event,feedback)
    select a.id,u.user_id,u.id,uid,newstatus,x.feedback from public.homework_submissions x where x.assignment_id=a.id and x.user_id=u.user_id;
  end if;
 end if;
 return jsonb_build_object('ok',true,'annotation_updated_at',(select updated_at from public.homework_annotations where upload_id=u.id));
end $function$;
revoke all on function public.homework_review(text,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.homework_review(text,jsonb) to postgres;
grant execute on function public.homework_review(text,jsonb) to authenticated;
grant execute on function public.homework_review(text,jsonb) to service_role;

-- homework_thumbnail_access(text,boolean)  md5=dbb991390121d37d886c299e4a6f3d3c
CREATE OR REPLACE FUNCTION public.homework_thumbnail_access(object_name text, writing boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(
  select 1 from public.homework_uploads u
  join public.homework_assignments a on a.id=u.assignment_id
  join auth.users x on x.id=auth.uid() and x.email_confirmed_at is not null
  where object_name=a.id::text||'/'||u.id::text||'.jpg' and u.submitted_at is not null
  and (u.file_name ~* '\.(png|jpe?g|webp|gif)$')
  and (
   (coalesce(public.is_teacher(),false) and a.owner_user_id=x.id)
   or (not coalesce(public.is_teacher(),false) and u.user_id=x.id and a.state<>'draft'
    and exists(select 1 from public.student_enrollments e where e.school_year=115 and e.email=lower(x.email)
     and e.class_code like '6%' and a.class_code in ('*',e.class_code))
    and (not writing or exists(select 1 from public.homework_submissions s where s.upload_id=u.id and s.status='submitted')))
  )
 );
$function$;
revoke all on function public.homework_thumbnail_access(text,boolean) from public, anon, authenticated, service_role;
grant execute on function public.homework_thumbnail_access(text,boolean) to postgres;
grant execute on function public.homework_thumbnail_access(text,boolean) to authenticated;
grant execute on function public.homework_thumbnail_access(text,boolean) to service_role;

-- partner_pilot.import_teacher_library_session(uuid)  md5=ff98627fa80e9f62f955961910611466
CREATE OR REPLACE FUNCTION partner_pilot.import_teacher_library_session(sid uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.quiz_sessions;d jsonb;pid text;g integer;n integer:=0;question_count integer;
 b jsonb;q jsonb;opts jsonb;correct_index integer;rich jsonb;source_url text;hash text;qid integer;
begin
 select * into s from public.quiz_sessions where id=sid and access_mode='practice' and library_visible and status='open' and school_year=115 for share;
 if s.id is null or exists(select 1 from public.quiz_generated_papers where session_id=sid)
 or exists(select 1 from public.quiz_learning_sessions where session_id=sid) then raise exception 'TEACHER_SOURCE_UNAVAILABLE';end if;
 select document into d from public.quiz_versions where id=s.version_id;
 if d#>>'{catalog,volume}' !~ '^[3469]年級' then raise exception 'TEACHER_GRADE_UNAVAILABLE';end if;
 g:=left(d#>>'{catalog,volume}',1)::int;
 if not partner_pilot.self_document_ok(d) then raise exception 'TEACHER_DOCUMENT_UNSUPPORTED';end if;
 perform public.quiz_validate(d);
 select count(*) into question_count from jsonb_array_elements(d->'blocks') x cross join lateral jsonb_array_elements(x->'questions') y;
 pid:='real-'||s.version_id;
 if exists(select 1 from partner_pilot.papers where id=pid) then
  if not exists(select 1 from partner_pilot.papers where id=pid and source_version=s.version_id and origin is null and total=question_count and is_real) then raise exception 'TEACHER_IMPORT_CONFLICT';end if;
  insert into partner_pilot.paper_sources values(pid,sid) on conflict do nothing;return pid;
 end if;
 for source_url in select distinct value#>>'{}' from jsonb_path_query(d,'$.blocks[*].**.media[*].url') a(value) loop
  if not exists(select 1 from public.quiz_media_assets where url=source_url and owner_id=s.owner_id) then raise exception 'TEACHER_MEDIA_UNAVAILABLE';end if;
 end loop;
 insert into partner_pilot.papers(id,title,grade,subject,kind,total,content_key,source_version,source_sha,is_real,source_session)
 values(pid,d->>'title',g,d#>>'{catalog,subject}','leaf',question_count,'teacher:'||s.version_id,s.version_id,encode(sha256(convert_to(d::text,'UTF8')),'hex'),true,sid);
 for source_url in select distinct value#>>'{}' from jsonb_path_query(d,'$.blocks[*].**.media[*].url') a(value) loop
  hash:=encode(sha256(convert_to(source_url,'UTF8')),'hex');insert into partner_pilot.media_map values(pid,hash,source_url);
  d:=replace(d::text,to_jsonb(source_url)::text,to_jsonb('https://partner-media.invalid/'||hash)::text)::jsonb;
 end loop;
 for b in select value from jsonb_array_elements(d->'blocks') loop
  q:=b->'questions'->0;n:=n+1;
  select jsonb_agg(o->'content' order by i),min((i-1)::int) filter(where o->>'id'=q#>>'{answer,option_id}') into opts,correct_index
  from jsonb_array_elements(q->'options') with ordinality a(o,i);
  rich:=jsonb_build_object('material',b->'material','prompt',q->'prompt','options',opts,'explanation',q->'explanation');
  qid:=nextval('partner_pilot.self_question_id');
  insert into partner_pilot.question_bank(id,title,prompt,options,correct,explanation,rich)
  values(qid,'第'||n||'題',q#>>'{prompt,text}',(select jsonb_agg(o->>'text' order by i) from jsonb_array_elements(opts) with ordinality a(o,i)),correct_index,q#>>'{explanation,text}',rich);
  insert into partner_pilot.paper_items values(pid,n,qid);
 end loop;
 insert into partner_pilot.paper_sources values(pid,sid);
 return pid;
end $function$;
revoke all on function partner_pilot.import_teacher_library_session(uuid) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.import_teacher_library_session(uuid) to postgres;

-- is_teacher()  md5=139dc315c99fc8c71be27a67523dbc84
CREATE OR REPLACE FUNCTION public.is_teacher()
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
                                                                                                                                        select lower(coalesce(auth.jwt() ->> 'email', '')) = any (
                                                                                                                                                array[
                                                                                                                                                            'chianwu@gmail.com'
                                                                                                                                                                    ]
                                                                                                                                                                        );
                                                                                                                                                                        $function$;
revoke all on function public.is_teacher() from public, anon, authenticated, service_role;
grant execute on function public.is_teacher() to public;
grant execute on function public.is_teacher() to postgres;
grant execute on function public.is_teacher() to anon;
