grant execute on function public.quiz_learning_wrong_items(integer) to service_role;

-- quiz_library_sessions(jsonb)  md5=d58d0d37f03a186e6fb640b306860150
CREATE OR REPLACE FUNCTION public.quiz_library_sessions(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb; papers jsonb;
begin
 identity:=public.quiz_student_identity();
 with visible as materialized (
  select s.id,s.version_id,s.status,s.access_mode,g.display_name,g.created_at saved_at,g.config,g.actual_distribution
  from public.quiz_sessions s left join public.quiz_generated_papers g on g.session_id=s.id and g.user_id=auth.uid()
  where (s.access_mode<>'practice' or s.library_visible) and s.access_mode in ('practice','self') and (s.access_mode<>'self' or (g.session_id is not null and g.deleted_at is null))
  and exists(select 1 from public.student_enrollments e where e.email=identity->>'email' and e.school_year=s.school_year and public.quiz_session_class_allowed(s.id,e.class_code))
 ), progress as (
  select a.session_id,count(x.question_id) answered,count(*) filter(where x.correct) correct
  from visible s join public.quiz_attempts a on a.session_id=s.id and a.user_id=auth.uid()
  left join public.quiz_answers x on x.attempt_id=a.id group by a.session_id
 )
 select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'version_id',s.version_id,'title',v.title,'catalog',v.catalog,'status',s.status,
 'generated',s.access_mode='self','display_name',s.display_name,'saved_at',s.saved_at,'generated_kind',s.config->>'kind',
 'unit_ids',s.config->'units','distribution',s.actual_distribution,
 'learning_point',case when s.config->>'kind'='extension' then regexp_replace(v.catalog->>'unit','^同重點再練習[：:]\s*','') else null end,
 'total',v.total,'answered',coalesce(p.answered,0),'correct',coalesce(p.correct,0))
 order by v.catalog->>'volume',v.catalog->>'subject',v.catalog->>'unit'),'[]') into papers
 from visible s join public.quiz_version_meta v on v.version_id=s.version_id left join progress p on p.session_id=s.id;
 return jsonb_build_object('sessions',papers,'role',identity->>'role','grade',identity->'grade','identity',public.quiz_nav_identity(identity->>'email'));
end $function$;
revoke all on function public.quiz_library_sessions(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_library_sessions(jsonb) to postgres;
grant execute on function public.quiz_library_sessions(jsonb) to authenticated;
grant execute on function public.quiz_library_sessions(jsonb) to service_role;

-- partner_pilot.quiz_math_answer_normalize(text)  md5=18239c7e6f3753b16e3369348004f359
CREATE OR REPLACE FUNCTION partner_pilot.quiz_math_answer_normalize(input text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare s text;n bigint;d bigint;a bigint;b bigint;t bigint;parts text[];fraction text;
begin
 if input is null or length(input)>250 then raise exception 'invalid_response';end if;
 s:=lower(regexp_replace(translate(input,'０１２３４５６７８９（）＋－＊／，＜＞＝−–—×÷','0123456789()+-*/,<>=---*/'),'[[:space:]　]','','g'));
 s:=replace(replace(replace(replace(s,'π','pi'),'√','sqrt'),'·','*'),'⋅','*');
 s:=translate(s,'ｒＲｄＤｐＰｉＩ','rrddppii');
 s:=regexp_replace(s,'sqrt([0-9]+)','sqrt(\1)','g');
 s:=regexp_replace(s,'\((pi|sqrt\([0-9]+\)|[a-z])\)','\1','g');
 s:=regexp_replace(s,'^\(([+-]?[0-9]{1,9}/[0-9]{1,9})\)\*?(pi|sqrt\([0-9]+\))$','\1*\2');
 -- Keep division grouping explicit: 8/3*pi means (8/3)*pi, never 8/(3*pi).
 s:=regexp_replace(s,'^([+-]?[0-9]{1,9})/([0-9]{1,9})\*(pi|sqrt\([0-9]+\))$','\1\3/\2');
 s:=regexp_replace(s,'([0-9)])\*(pi|sqrt|\()','\1\2','g');
 if length(s)=0 or s!~'^[a-z0-9()+*/.,<>=-]+$' then raise exception 'invalid_response';end if;
 if s~'^\([^,]*,[^,]*\)$' then
  parts:=string_to_array(substr(s,2,length(s)-2),',');
  return '('||partner_pilot.quiz_math_answer_normalize(parts[1])||','||partner_pilot.quiz_math_answer_normalize(parts[2])||')';
 end if;
 while s~'^\([+0-9./-]+\)$' loop s:=substr(s,2,length(s)-2);end loop;
 if s~'^[+-]?[0-9]{1,12}$' then return (s::bigint)::text;end if;
 if s~'^[+-]?[0-9]{1,9}/[0-9]{1,9}$' then n:=split_part(s,'/',1)::bigint;d:=split_part(s,'/',2)::bigint;
 elsif s~'^[+-]?[0-9]{1,9}\.[0-9]{1,8}$' then
  fraction:=split_part(s,'.',2);d:=power(10::numeric,length(fraction))::bigint;n:=(s::numeric*d)::bigint;
 else return s;end if;
 if d=0 then raise exception 'invalid_response';end if;
 a:=abs(n);b:=d;while b<>0 loop t:=a%b;a:=b;b:=t;end loop;
 n:=n/a;d:=d/a;return case when d=1 then n::text else n::text||'/'||d::text end;
end $function$;
revoke all on function partner_pilot.quiz_math_answer_normalize(text) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.quiz_math_answer_normalize(text) to postgres;

