-- quiz_media_access(text,uuid)  md5=fecfabfd996fcc9d8518c9fdcc272e58
CREATE OR REPLACE FUNCTION public.quiz_media_access(p_url text, p_attempt uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r public.quiz_question_reports;asset public.quiz_media_assets;
begin
 if auth.uid() is null then raise exception 'login_required';end if;
 if coalesce(public.is_teacher(),false) then
  select * into r from public.quiz_question_reports where id=p_attempt;
  if r.id is not null then
   if not exists(select 1 from jsonb_path_query(r.snapshot,'$.**.url') u where u#>>'{}'=p_url)
    and not exists(select 1 from jsonb_path_query(r.snapshot,'$.**.referenceUrl') u where u#>>'{}'=p_url) then raise exception 'media_unavailable';end if;
   select * into asset from public.quiz_media_assets where url=p_url;
   if asset.url is null then raise exception 'media_unavailable';end if;
   return to_jsonb(asset)||case when r.source='past' then jsonb_build_object('backend','supabase') else '{}'::jsonb end;
  end if;
 end if;
 return public.quiz_media_access_before_reports(p_url,p_attempt);
end$function$;
revoke all on function public.quiz_media_access(text,uuid) from public, anon, authenticated, service_role;
grant execute on function public.quiz_media_access(text,uuid) to postgres;
grant execute on function public.quiz_media_access(text,uuid) to authenticated;
grant execute on function public.quiz_media_access(text,uuid) to service_role;

-- quiz_media_access_before_past(text,uuid)  md5=299d8bdc774d554f83ed024943ad8cc6
CREATE OR REPLACE FUNCTION public.quiz_media_access_before_past(p_url text, p_attempt uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare asset public.quiz_media_assets;
begin
 if auth.uid() is null then raise exception 'login_required';end if;
 select * into asset from public.quiz_media_assets where url=p_url;
 if asset.url is null then raise exception 'media_unavailable';end if;
 if coalesce(public.is_teacher(),false) and asset.owner_id=auth.uid() then return to_jsonb(asset);end if;
 if not public.quiz_media_visible(p_url,p_attempt) then raise exception 'media_unavailable';end if;
 return to_jsonb(asset);
end $function$;
revoke all on function public.quiz_media_access_before_past(text,uuid) from public, anon, authenticated, service_role;
grant execute on function public.quiz_media_access_before_past(text,uuid) to postgres;
grant execute on function public.quiz_media_access_before_past(text,uuid) to service_role;

-- quiz_media_access_before_reports(text,uuid)  md5=4f8ac6502ef5bc43ba7528ff5bbcbdcc
CREATE OR REPLACE FUNCTION public.quiz_media_access_before_reports(p_url text, p_attempt uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare att public.quiz_past_attempts;paper public.quiz_past_papers;d jsonb;asset public.quiz_media_assets;identity jsonb;
begin
 if auth.uid() is null then raise exception 'login_required';end if;
 if coalesce(public.is_teacher(),false) then
  select * into asset from public.quiz_media_assets where url=p_url and owner_id=auth.uid();
  if asset.url is not null and exists(select 1 from public.quiz_past_versions v join public.quiz_past_papers p on p.id=v.paper_id where p.owner_id=auth.uid() and (public.quiz_past_has_media(v.document,p_url) or exists(select 1 from jsonb_array_elements(v.document->'groups') g where g->>'referenceUrl'=p_url))) then return to_jsonb(asset)||jsonb_build_object('backend','supabase');end if;
 end if;
 select * into att from public.quiz_past_attempts where id=p_attempt;
 if att.id is null then return public.quiz_media_access_before_past(p_url,p_attempt);end if;
 identity:=public.quiz_student_identity();select * into paper from public.quiz_past_papers where id=att.paper_id;
 if att.user_id<>auth.uid() or identity->>'role' is distinct from 'student' or not paper.enabled or paper.grade<>(identity->>'grade')::integer then raise exception 'media_unavailable';end if;
 select document into d from public.quiz_past_versions where id=att.version_id;
 if not public.quiz_past_has_media(d,p_url) and not exists(select 1 from jsonb_array_elements(d->'groups') g where g->>'referenceUrl'=p_url and exists(select 1 from public.quiz_past_receipts r where r.attempt_id=att.id and r.group_id=g->>'id' and r.status='self_checked')) then raise exception 'media_unavailable';end if;
 select * into asset from public.quiz_media_assets where url=p_url and owner_id=paper.owner_id;if asset.url is null then raise exception 'media_unavailable';end if;
 return to_jsonb(asset)||jsonb_build_object('backend','supabase');
end$function$;
revoke all on function public.quiz_media_access_before_reports(text,uuid) from public, anon, authenticated, service_role;
grant execute on function public.quiz_media_access_before_reports(text,uuid) to postgres;
grant execute on function public.quiz_media_access_before_reports(text,uuid) to service_role;

-- quiz_media_visible(text,uuid)  md5=71bb4be8d16988c6182d67f9edcab29a
CREATE OR REPLACE FUNCTION public.quiz_media_visible(p_url text, p_attempt uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid(); teacher boolean:=coalesce(public.is_teacher(),false); att public.quiz_attempts; sess public.quiz_sessions;
 d jsonb; b jsonb; q jsonb; done boolean; groupdone boolean; v_email text;
begin
 select * into att from public.quiz_attempts where id=p_attempt and user_id=uid;
 if att.id is null then raise exception 'media_unavailable';end if;
 select * into sess from public.quiz_sessions where id=att.session_id;
 if sess.id is null then raise exception 'session_unavailable';end if;
 if sess.access_mode='self' and not exists(select 1 from public.quiz_generated_papers where session_id=sess.id and user_id=uid) then raise exception 'session_unavailable';end if;
 -- quiz_action rejects teacher resume, including personal sessions.
 if teacher then raise exception 'student_required';end if;
 if sess.access_mode='personal' then raise exception 'session_unavailable';end if;
 select lower(u.email) into v_email from auth.users u where u.id=uid and u.email_confirmed_at is not null;
 if not exists(select 1 from public.student_enrollments e where e.email=v_email and e.school_year=sess.school_year and public.quiz_session_class_allowed(sess.id,e.class_code)) then raise exception 'roster_required';end if;
 select document into d from public.quiz_versions where id=sess.version_id;
 -- Match the immutable attempt's question and option orders, including material.
 if exists(select 1 from jsonb_array_elements(d->'blocks') bx cross join lateral jsonb_array_elements(bx->'questions') qx
  where att.question_order ? (qx->>'id') and (
   exists(select 1 from jsonb_path_query(jsonb_build_array(bx->'material',qx->'prompt'),'$.**.media[*].url') u where u#>>'{}'=p_url)
   or exists(select 1 from jsonb_array_elements(coalesce(qx->'options','[]')) o
    where coalesce(att.option_orders->(qx->>'id'),'[]') ? (o->>'id')
    and exists(select 1 from jsonb_path_query(o->'content','$.**.media[*].url') u where u#>>'{}'=p_url)))) then return true;end if;
 select count(*)=jsonb_array_length(att.question_order) into done from public.quiz_answers where attempt_id=att.id;
 for b in select value from jsonb_array_elements(d->'blocks') loop
  select not exists(select 1 from jsonb_array_elements(b->'questions') x where not exists(select 1 from public.quiz_answers a where a.attempt_id=att.id and a.question_id=x->>'id')) into groupdone;
  if (sess.reveal='complete' and done) or (sess.reveal='immediate' and groupdone) then
   if exists(select 1 from jsonb_array_elements(b->'questions') x cross join lateral jsonb_path_query(x->'explanation','$.**.media[*].url') u where u#>>'{}'=p_url) then return true;end if;
  end if;
 end loop;
 return false;
end $function$;
revoke all on function public.quiz_media_visible(text,uuid) from public, anon, authenticated, service_role;
grant execute on function public.quiz_media_visible(text,uuid) to postgres;
grant execute on function public.quiz_media_visible(text,uuid) to service_role;

-- quiz_monitor(jsonb)  md5=9ba08c64982165bae18e39c0df2d00c4
CREATE OR REPLACE FUNCTION public.quiz_monitor(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from public.quiz_learning_sessions where session_id=(p_data->>'session_id')::uuid) then raise exception 'session_unavailable';end if;
 return public.quiz_monitor_before_learning(p_data);
end$function$;
revoke all on function public.quiz_monitor(jsonb) from public, anon, authenticated, service_role;
