-- quiz_rewards_before_learning(jsonb)  md5=b4047f9c1c3885f1e6ba9ead2540b74d
CREATE OR REPLACE FUNCTION public.quiz_rewards_before_learning(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old jsonb;normal jsonb;flowers jsonb;cid text:=p_data->>'course_id';
begin
 old:=public.quiz_rewards_before_past_flowers(p_data);
 select coalesce(jsonb_agg(a order by n),'[]') into normal
 from jsonb_array_elements(coalesce(old->'awards','[]')) with ordinality x(a,n)
 where a->>'source_type' is distinct from 'past_exam';
 select coalesce(jsonb_agg((a-'half_units')||jsonb_build_object('reward_kind','past-exam-flower','flower_style','forest') order by n),'[]') into flowers
 from jsonb_array_elements(coalesce(old->'awards','[]')) with ordinality x(a,n)
 where a->>'source_type'='past_exam' and (cid is null or cid='grade'||(a->>'grade')||'-115-1');
 return old||jsonb_build_object('awards',normal,'flowers',flowers);
end$function$;
revoke all on function public.quiz_rewards_before_learning(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_rewards_before_learning(jsonb) to postgres;
grant execute on function public.quiz_rewards_before_learning(jsonb) to service_role;

-- quiz_rewards_before_partner(jsonb)  md5=036627e73866fe77ed8fa8a71e11195e
CREATE OR REPLACE FUNCTION public.quiz_rewards_before_partner(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare data jsonb;cfg public.quiz_learning_settings;awards jsonb;identity jsonb;begin
 data:=public.quiz_rewards_before_learning(p_data);if coalesce(public.is_teacher(),false) then return data;end if;
 select * into cfg from public.quiz_learning_settings where id;if not cfg.enabled then return data;end if;
 begin identity:=public.quiz_student_identity();exception when raise_exception then if sqlerrm in ('roster_required','student_required') then return data;else raise;end if;end;
 if identity->>'role' is distinct from 'student' then return data;end if;
 if p_data ? 'course_id' and p_data->>'course_id'<>'grade'||(identity->>'grade')||'-'||cfg.school_year||'-'||cfg.semester then return data;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id','learning:'||l.school_year||':'||l.semester||':'||l.ordinal,'source_type','learning','title','練習累積・第'||l.ordinal||'片延伸葉','grade',(identity->>'grade')::integer,'half_units',2,'total',10,'correct',null,'awarded_at',l.created_at,'ordinal',l.ordinal) order by l.ordinal),'[]') into awards from public.quiz_learning_leaves l where l.user_id=auth.uid() and l.school_year=cfg.school_year and l.semester=cfg.semester;
 -- Full two-unit learning awards go first: they cannot consume/relabel an older pending half.
 -- Existing garden_growth already reads awards and therefore receives the same stable IDs.
 return data||jsonb_build_object('awards',awards||coalesce(data->'awards','[]'),'learning',public.quiz_learning_summary(),'learningAwards',awards);
end$function$;
revoke all on function public.quiz_rewards_before_partner(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_rewards_before_partner(jsonb) to postgres;
grant execute on function public.quiz_rewards_before_partner(jsonb) to service_role;

-- quiz_rewards_before_past(jsonb)  md5=6ee947023bcea926b2c5ad180b99d757
CREATE OR REPLACE FUNCTION public.quiz_rewards_before_past(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb;g integer;items jsonb;
begin
 if coalesce(public.is_teacher(),false) then return jsonb_build_object('awards','[]'::jsonb);end if;
 identity:=public.quiz_student_identity();if identity->>'role'<>'student' then return jsonb_build_object('awards','[]'::jsonb);end if;
 g:=(identity->>'grade')::integer;
 if p_data ? 'course_id' and p_data->>'course_id'<>'grade'||g||'-115-1' then raise exception 'course_unavailable';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.id,'session_id',a.session_id,'title',coalesce(p.display_name,v.document->>'title'),'grade',w.grade,'total',w.total,'correct',w.correct,'awarded_at',w.awarded_at) order by w.awarded_at),'[]') into items
 from public.quiz_leaf_awards w join public.quiz_attempts a on a.id=w.attempt_id join public.quiz_sessions s on s.id=a.session_id join public.quiz_versions v on v.id=s.version_id left join public.quiz_generated_papers p on p.session_id=s.id
 where w.user_id=auth.uid() and w.grade=g;
 return jsonb_build_object('awards',items);
end $function$;
revoke all on function public.quiz_rewards_before_past(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_rewards_before_past(jsonb) to postgres;
grant execute on function public.quiz_rewards_before_past(jsonb) to service_role;

-- quiz_rewards_before_past_flowers(jsonb)  md5=9265f3fba1da520b1baa28e96f2142f3
CREATE OR REPLACE FUNCTION public.quiz_rewards_before_past_flowers(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare original jsonb;items jsonb;identity jsonb;begin
 original:=public.quiz_rewards_before_past(p_data);if coalesce(public.is_teacher(),false) then return original;end if;
 identity:=public.quiz_student_identity();if identity->>'role' is distinct from 'student' then return original;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id','past:'||l.id,'source_type','past_exam','paper_id',p.id,'attempt_id',a.id,'title',p.title,'grade',p.grade,'total',a.max_score,'correct',a.score,'half_units',2,'awarded_at',l.awarded_at) order by l.awarded_at,l.id),'[]') into items
 from public.quiz_past_leaves l join public.quiz_past_attempts a on a.id=l.attempt_id join public.quiz_past_papers p on p.id=l.paper_id where l.user_id=auth.uid() and l.school_year=115 and l.semester=1 and p.grade=(identity->>'grade')::integer;
 return jsonb_set(original,'{awards}',coalesce(original->'awards','[]')||items);
end$function$;
revoke all on function public.quiz_rewards_before_past_flowers(jsonb) from public, anon, authenticated, service_role;
