-- quiz_session_class_allowed(uuid,text)  md5=01f5c8c3e05c49bc41799c8f4016e838
CREATE OR REPLACE FUNCTION public.quiz_session_class_allowed(p_session uuid, p_class text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce((select case
  when s.access_mode='practice' and m.catalog->>'volume' ~ '^[3469]年級'
   and not exists(select 1 from public.quiz_generated_papers g where g.session_id=s.id)
   and not exists(select 1 from public.quiz_learning_sessions l where l.session_id=s.id)
  then (p_class ~ '^[3469][0-9]{2}$' and left(p_class,1)=left(m.catalog->>'volume',1)
   and (s.library_visible or exists(select 1 from public.quiz_attempts a where a.session_id=s.id and a.user_id=auth.uid())))
   or (not s.library_visible and s.class_codes ? p_class)
  else s.class_codes ? p_class end
 from public.quiz_sessions s left join public.quiz_version_meta m on m.version_id=s.version_id where s.id=p_session),false)
$function$;
revoke all on function public.quiz_session_class_allowed(uuid,text) from public, anon, authenticated, service_role;
grant execute on function public.quiz_session_class_allowed(uuid,text) to postgres;

-- quiz_student_document(jsonb,jsonb,jsonb)  md5=5683cf3560f90306dac5c02b4f699e08
CREATE OR REPLACE FUNCTION public.quiz_student_document(d jsonb, qo jsonb, oo jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 with source as materialized (
  select distinct on(q->>'id') q->>'id' id,b,q
  from jsonb_array_elements(d->'blocks') with ordinality bx(b,bn),
   lateral jsonb_array_elements(b->'questions') with ordinality qx(q,qn)
  order by q->>'id',bn,qn
 ), items as (
  select r.n,jsonb_build_object('id',q->>'id','type',q->>'type','prompt',q->'prompt',
   'block_id',b->>'id','material',b->'material','options',
   (select coalesce(jsonb_agg(jsonb_build_object('id',o->>'id','content',o->'content') order by ord),'[]'::jsonb)
    from jsonb_array_elements(coalesce(q->'options','[]')) o
    join jsonb_array_elements_text(coalesce(oo->(q->>'id'),'[]')) with ordinality opt(id,ord) on o->>'id'=opt.id)) item
  from jsonb_array_elements(qo) with ordinality r(qid,n)
  left join source on source.id=r.qid#>>'{}'
 ) select jsonb_build_object('title',d->>'title','questions',coalesce(jsonb_agg(item order by n),'[]'::jsonb)) from items;
$function$;
revoke all on function public.quiz_student_document(jsonb,jsonb,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_student_document(jsonb,jsonb,jsonb) to postgres;
grant execute on function public.quiz_student_document(jsonb,jsonb,jsonb) to service_role;

-- quiz_student_identity()  md5=cbe8aa2dc5f96e95bb552eec6fab9e4c
CREATE OR REPLACE FUNCTION public.quiz_student_identity()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare uid uuid:=auth.uid();mail text;cls text;
begin
 if uid is null then raise exception 'login_required';end if;
 if coalesce(public.is_teacher(),false) then raise exception 'student_required';end if;
 select lower(u.email) into mail from auth.users u where u.id=uid and u.email_confirmed_at is not null;
 select e.class_code into cls from public.student_enrollments e where e.email=mail and e.school_year=115 and e.class_code ~ '^[3469][0-9]{2}$';
 if cls is null then raise exception 'roster_required';end if;
 return jsonb_build_object('role','student','grade',left(cls,1)::integer,'email',mail,'class_code',cls);
end $function$;
revoke all on function public.quiz_student_identity() from public, anon, authenticated, service_role;
grant execute on function public.quiz_student_identity() to postgres;
grant execute on function public.quiz_student_identity() to service_role;

-- quiz_study_immutable()  md5=9546560cf92b8ad03f9ae274ec9e6260
CREATE OR REPLACE FUNCTION public.quiz_study_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then raise exception 'study_fixed_version';end if;
 if tg_table_name in('quiz_textbooks','quiz_study_packages') and (to_jsonb(new)-'enabled')=(to_jsonb(old)-'enabled') then return new;end if;
 raise exception 'study_fixed_version';
end$function$;
