-- quiz_study_payload(text,uuid,uuid,jsonb)  md5=217af41e87b728299f490684e66860b0
CREATE OR REPLACE FUNCTION public.quiz_study_payload(p_kind text, p_attempt uuid, p_version uuid, p_disclosed jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb;d jsonb;pkg public.quiz_study_packages;link public.quiz_study_items;
 refs jsonb:='{}';explanations jsonb:='{}';pages jsonb;ref jsonb;known boolean;book_ids uuid[]:='{}';key text;field jsonb;
begin
 if not exists(select 1 from public.quiz_study_attempts where kind=p_kind and attempt_id=p_attempt and version_id=p_version)
  and not exists(select 1 from public.quiz_study_packages where kind=p_kind and version_id=p_version and enabled and approved) then return '{}'::jsonb;end if;
 if p_kind='normal' and coalesce(public.is_teacher(),false) then
  -- The existing teacher trial joins only an owned session. Derive this book's
  -- grade from that fixed version, never from a browser-provided identity.
  select jsonb_build_object('grade',substring(v.document->'catalog'->>'volume' from '^([3469])')::integer) into identity
   from public.quiz_attempts a join public.quiz_sessions s on s.id=a.session_id join public.quiz_versions v on v.id=s.version_id
   where a.id=p_attempt and a.user_id=auth.uid() and s.owner_id=auth.uid() and v.id=p_version;
  if identity is null then raise exception 'attempt_unavailable';end if;
 else identity:=public.quiz_student_identity();end if;
 if p_kind='normal' then
  select v.document into d from public.quiz_attempts a join public.quiz_sessions s on s.id=a.session_id
   join public.quiz_versions v on v.id=s.version_id where a.id=p_attempt and a.user_id=auth.uid() and v.id=p_version;
 elsif p_kind='past' then
  select v.document into d from public.quiz_past_attempts a join public.quiz_past_versions v on v.id=a.version_id
   join public.quiz_past_papers p on p.id=a.paper_id where a.id=p_attempt and a.user_id=auth.uid() and v.id=p_version and p.grade=(identity->>'grade')::integer;
 else raise exception 'study_unavailable';end if;
 if d is null then raise exception 'attempt_unavailable';end if;
 select p.* into pkg from public.quiz_study_attempts a join public.quiz_study_packages p on p.id=a.package_id
  where a.kind=p_kind and a.attempt_id=p_attempt and a.version_id=p_version;
 if pkg.id is null then
  select * into pkg from public.quiz_study_packages p where p.kind=p_kind and p.version_id=p_version and p.enabled and p.approved order by p.created_at desc,p.id desc limit 1;
  if pkg.id is null then return '{}'::jsonb;end if;
  insert into public.quiz_study_attempts values(p_kind,p_attempt,p_version,pkg.id) on conflict do nothing;
  select p.* into pkg from public.quiz_study_attempts a join public.quiz_study_packages p on p.id=a.package_id where a.kind=p_kind and a.attempt_id=p_attempt and a.version_id=p_version;
 end if;
 if not pkg.enabled or not pkg.approved then return '{}'::jsonb;end if;
 for link in select * from public.quiz_study_items where package_id=pkg.id order by group_id,question_id loop
  if p_kind='normal' then
   known:=link.group_id='' and exists(select 1 from jsonb_array_elements(d->'blocks') b,jsonb_array_elements(b->'questions') q where q->>'id'=link.question_id);
   key:=link.question_id;
  else
   known:=exists(select 1 from jsonb_array_elements(d->'groups') g,jsonb_array_elements(g->'fields') f where g->>'id'=link.group_id and f->>'id'=link.question_id);
   key:=link.group_id;
  end if;
  if not known then continue;end if;
  if link.book_id is not null and exists(select 1 from public.quiz_textbooks b where b.id=link.book_id and b.enabled and b.grade=(identity->>'grade')::integer)
   and not exists(select 1 from unnest(link.reference_pages) n where not exists(select 1 from public.quiz_textbook_pages p where p.book_id=link.book_id and n=any(p.printed_pages))) then
   if not link.book_id=any(book_ids) then book_ids:=array_append(book_ids,link.book_id);end if;
   ref:=refs->key;
   if ref is null then ref:=jsonb_build_object('bookId',link.book_id,'primary',link.primary_page,'references',to_jsonb(link.reference_pages),'fields','[]'::jsonb);
   elsif ref->>'bookId'=link.book_id::text then ref:=jsonb_set(ref,'{references}',(ref->'references')||to_jsonb(link.reference_pages));end if;
   if p_kind='past' and ref->>'bookId'=link.book_id::text then ref:=jsonb_set(ref,'{fields}',(ref->'fields')||jsonb_build_array(jsonb_build_object('questionId',link.question_id,'page',link.primary_page)));end if;
   refs:=jsonb_set(refs,array[key],ref);
  end if;
  if link.student_explanation is not null and p_disclosed ? link.question_id then
   explanations:=jsonb_set(explanations,array[link.question_id],jsonb_build_object('text',link.student_explanation,'origin',link.origin));
  end if;
 end loop;
 select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'bookId',p.book_id,'printedPages',p.printed_pages,
  'sequence',p.book_id::text||':'||p.sequence,'url','https://quiz-media.invalid/'||p.book_id::text||'/'||p.sha256) order by p.book_id,p.printed_pages[1]),'[]') into pages
  from public.quiz_textbook_pages p where p.book_id=any(book_ids);
 return jsonb_build_object('schema',1,'kind',p_kind,'attemptId',p_attempt,'versionId',p_version,'packageId',pkg.id,'pages',pages,'references',refs,'explanations',explanations);
end$function$;
revoke all on function public.quiz_study_payload(text,uuid,uuid,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_study_payload(text,uuid,uuid,jsonb) to postgres;
grant execute on function public.quiz_study_payload(text,uuid,uuid,jsonb) to service_role;

-- quiz_textbook_media_access(text,uuid,uuid,text)  md5=8725d984bc5c17f5869da438e9ce97da
CREATE OR REPLACE FUNCTION public.quiz_textbook_media_access(p_kind text, p_attempt uuid, p_version uuid, p_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare study jsonb;page jsonb;asset public.quiz_textbook_pages;
begin
 study:=public.quiz_study_payload(p_kind,p_attempt,p_version);
 select value into page from jsonb_array_elements(coalesce(study->'pages','[]')) where value->>'url'=p_url;
 if page is null then raise exception 'media_unavailable';end if;
 select * into asset from public.quiz_textbook_pages p where p.book_id=(page->>'bookId')::uuid and p.id=page->>'id';
 if asset.id is null then raise exception 'media_unavailable';end if;
 return jsonb_build_object('url',p_url,'mime','image/webp','bytes',asset.bytes,'backend','drive');
end$function$;
revoke all on function public.quiz_textbook_media_access(text,uuid,uuid,text) from public, anon, authenticated, service_role;
grant execute on function public.quiz_textbook_media_access(text,uuid,uuid,text) to postgres;
grant execute on function public.quiz_textbook_media_access(text,uuid,uuid,text) to authenticated;
grant execute on function public.quiz_textbook_media_access(text,uuid,uuid,text) to service_role;

-- quiz_valid_content(jsonb)  md5=e75d9e82d4604ea5593c8fd14d283e66
CREATE OR REPLACE FUNCTION public.quiz_valid_content(c jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare m jsonb; part jsonb; row_value jsonb; cell jsonb; columns integer; total_text integer:=0;
begin
 if jsonb_typeof(c) is distinct from 'object' or jsonb_typeof(c->'text') is distinct from 'string'
  or length(c->>'text')>20000 or jsonb_typeof(c->'media') is distinct from 'array' then return false; end if;
 if exists(select 1 from jsonb_object_keys(c) x where x not in ('text','media','layout')) then return false; end if;
 if jsonb_array_length(c->'media')>8 then return false; end if;
 for m in select value from jsonb_array_elements(c->'media') loop
  if m->>'kind' is null or m->>'kind' not in ('image','audio') or jsonb_typeof(m->'url') is distinct from 'string'
   or (m->>'url') !~ '^https://[^[:space:]<>]+$' or length(m->>'url')>2000
   or jsonb_typeof(m->'alt') is distinct from 'string' or length(m->>'alt')>500 then return false; end if;
  if exists(select 1 from jsonb_object_keys(m) x where x not in ('kind','url','alt')) then return false; end if;
 end loop;
 if c ? 'layout' then
  if jsonb_typeof(c->'layout') is distinct from 'array' then return false; end if;
  if jsonb_array_length(c->'layout') not between 1 and 100 then return false; end if;
  for part in select value from jsonb_array_elements(c->'layout') loop
   if jsonb_typeof(part) is distinct from 'object' then return false; end if;
   if part->>'type'='paragraph' then
    if not public.quiz_valid_runs(part->'runs',c->'media') or exists(select 1 from jsonb_object_keys(part) k where k not in ('type','runs')) then return false; end if;
    select total_text+coalesce(sum(length(r->>'text')),0) into total_text from jsonb_array_elements(part->'runs') r where r->>'type'='text';
   elsif part->>'type'='table' then
    if jsonb_typeof(part->'rows') is distinct from 'array' or exists(select 1 from jsonb_object_keys(part) k where k not in ('type','rows')) then return false; end if;
    if jsonb_array_length(part->'rows') not between 1 and 30 then return false; end if;
    columns:=null;
    for row_value in select value from jsonb_array_elements(part->'rows') loop
     if jsonb_typeof(row_value) is distinct from 'array' then return false; end if;
     if jsonb_array_length(row_value) not between 1 and 12 or (columns is not null and jsonb_array_length(row_value)<>columns) then return false; end if;
     columns:=jsonb_array_length(row_value);
     for cell in select value from jsonb_array_elements(row_value) loop
      if not public.quiz_valid_runs(cell,c->'media') then return false; end if;
      select total_text+coalesce(sum(length(r->>'text')),0) into total_text from jsonb_array_elements(cell) r where r->>'type'='text';
     end loop;
    end loop;
   else return false; end if;
  end loop;
  if total_text>20000 then return false; end if;
 end if;
 return true;
end $function$;
revoke all on function public.quiz_valid_content(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_valid_content(jsonb) to postgres;
grant execute on function public.quiz_valid_content(jsonb) to service_role;

-- quiz_valid_runs(jsonb,jsonb)  md5=a78d9484bdc3daa06e21066f5eca69c2
CREATE OR REPLACE FUNCTION public.quiz_valid_runs(runs jsonb, media jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare r jsonb; idx integer; w numeric;
begin
 if jsonb_typeof(runs) is distinct from 'array' then return false; end if;
 if jsonb_array_length(runs)>200 then return false; end if;
 for r in select value from jsonb_array_elements(runs) loop
  if jsonb_typeof(r) is distinct from 'object' then return false; end if;
  if r->>'type'='text' then
   if jsonb_typeof(r->'text') is distinct from 'string' or length(r->>'text')>20000
    or exists(select 1 from jsonb_object_keys(r) k where k not in ('type','text')) then return false; end if;
  elsif r->>'type'='image' then
   if jsonb_typeof(r->'media_index') is distinct from 'number' or (r->>'media_index') !~ '^[0-7]$'
    or jsonb_typeof(r->'width') is distinct from 'number'
    or exists(select 1 from jsonb_object_keys(r) k where k not in ('type','media_index','width')) then return false; end if;
   idx:=(r->>'media_index')::integer; w:=(r->>'width')::numeric;
   if media->idx->>'kind' is distinct from 'image' or w<12 or w>800 then return false; end if;
  else return false; end if;
 end loop;
 return true;
end $function$;
revoke all on function public.quiz_valid_runs(jsonb,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_valid_runs(jsonb,jsonb) to postgres;
grant execute on function public.quiz_valid_runs(jsonb,jsonb) to service_role;

-- quiz_validate(jsonb)  md5=64c1481d0c70f11162d71b1df5975783
CREATE OR REPLACE FUNCTION public.quiz_validate(d jsonb)
 RETURNS void
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare b jsonb; q jsonb; o jsonb; a jsonb; ids text[]:='{}'; bids text[]:='{}'; opts text[]; n integer:=0; k text;
begin
 if jsonb_typeof(d) is distinct from 'object' or d->>'schema' is distinct from '1'
  or jsonb_typeof(d->'title') is distinct from 'string' or length(trim(d->>'title')) not between 1 and 200
  or jsonb_typeof(d->'catalog') is distinct from 'object' or length((d->'catalog')::text)>4000
  or jsonb_typeof(d->'blocks') is distinct from 'array' then raise exception 'invalid_document'; end if;
 if jsonb_array_length(d->'blocks') not between 1 and 100 then raise exception 'invalid_document'; end if;
 for b in select value from jsonb_array_elements(d->'blocks') loop
  if coalesce(b->>'id','') !~ '^[a-zA-Z0-9_-]{1,80}$' or b->>'id'=any(bids)
   or not public.quiz_valid_content(b->'material') or jsonb_typeof(b->'questions') is distinct from 'array' then raise exception 'invalid_block'; end if;
  bids:=array_append(bids,b->>'id');
  if jsonb_array_length(b->'questions') not between 1 and 30 then raise exception 'invalid_block'; end if;
  for q in select value from jsonb_array_elements(b->'questions') loop
   n:=n+1;
   if coalesce(q->>'id','') !~ '^[a-zA-Z0-9_-]{1,80}$' or q->>'id'=any(ids)
    or not public.quiz_valid_content(q->'prompt') or not public.quiz_valid_content(q->'explanation')
    or length(trim(q->'prompt'->>'text'))=0 or jsonb_typeof(q->'answer') is distinct from 'object' then raise exception 'invalid_question'; end if;
   ids:=array_append(ids,q->>'id');
   if q->>'type'='single' then
    if jsonb_typeof(q->'options') is distinct from 'array' then raise exception 'invalid_options'; end if;
    if jsonb_array_length(q->'options') not between 2 and 8 then raise exception 'invalid_options'; end if;
    opts:='{}';
    for o in select value from jsonb_array_elements(q->'options') loop
     if coalesce(o->>'id','') !~ '^[a-zA-Z0-9_-]{1,80}$' or o->>'id'=any(opts)
      or not public.quiz_valid_content(o->'content') then raise exception 'invalid_options'; end if;
     opts:=array_append(opts,o->>'id');
    end loop;
    if not coalesce(q->'answer'->>'option_id'=any(opts),false) then raise exception 'invalid_answer'; end if;
   elsif q->>'type'='short' then
    if q ? 'options' then raise exception 'invalid_options'; end if;
    if jsonb_typeof(q->'answer'->'accepted') is distinct from 'array' then raise exception 'invalid_answer'; end if;
    if jsonb_array_length(q->'answer'->'accepted') not between 1 and 20 then raise exception 'invalid_answer'; end if;
    for a in select value from jsonb_array_elements(q->'answer'->'accepted') loop
     if jsonb_typeof(a) is distinct from 'string' or length(trim(a#>>'{}')) not between 1 and 2000 then raise exception 'invalid_answer'; end if;
    end loop;
   else raise exception 'invalid_question_type'; end if;
   -- 白名單投影仍是學生回傳的唯一來源，不信任教師輸入的額外欄位。
   for k in select jsonb_object_keys(q) loop
    if k not in ('id','type','prompt','explanation','options','answer') then raise exception 'invalid_question_field'; end if;
   end loop;
  end loop;
 end loop;
 if n>200 or octet_length(d::text)>1000000 then raise exception 'document_too_large'; end if;
end $function$;
revoke all on function public.quiz_validate(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_validate(jsonb) to postgres;
grant execute on function public.quiz_validate(jsonb) to service_role;

-- quiz_version_browser(jsonb)  md5=402efbd46df08e921cad761b620c8448
CREATE OR REPLACE FUNCTION public.quiz_version_browser(p_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare bank uuid:=(p_data->>'bank_id')::uuid; result jsonb;
begin
 if auth.uid() is null then raise exception 'login_required';end if;
 if not coalesce(public.is_teacher(),false) then raise exception 'teacher_required';end if;
 if not exists(select 1 from public.quiz_banks where id=bank and owner_id=auth.uid()) then raise exception 'bank_unavailable';end if;
 if coalesce(p_data->>'action','list')='get' then
  select to_jsonb(v) into result from public.quiz_versions v where v.bank_id=bank and v.id=(p_data->>'version_id')::uuid;
  if result is null then raise exception 'version_unavailable';end if;return result;
 elsif coalesce(p_data->>'action','list')<>'list' then raise exception 'invalid_request';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'bank_id',v.bank_id,'revision',v.revision,'created_at',v.created_at,'title',m.title,'catalog',m.catalog,'total',m.total) order by v.revision desc),'[]') into result
 from public.quiz_versions v join public.quiz_version_meta m on m.version_id=v.id where v.bank_id=bank;
 return jsonb_build_object('versions',result);
end $function$;
revoke all on function public.quiz_version_browser(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_version_browser(jsonb) to postgres;
grant execute on function public.quiz_version_browser(jsonb) to authenticated;
grant execute on function public.quiz_version_browser(jsonb) to service_role;

