-- quiz_wrong_questions(jsonb)  md5=4c0f07bb627fba386927ea05c8833738
CREATE OR REPLACE FUNCTION public.quiz_wrong_questions(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb;old jsonb;items jsonb;facets jsonb;n integer;page integer:=coalesce((p_data->>'page')::integer,0);include_past boolean:=p_data->>'learning_client'='1';begin
 p_data:=p_data-'learning_client';
 identity:=public.quiz_student_identity();if identity->>'role' is distinct from 'student' then raise exception 'student_required';end if;
 if coalesce((p_data->>'grade')::integer,(identity->>'grade')::integer) is distinct from (identity->>'grade')::integer then raise exception 'course_unavailable';end if;
 if coalesce(p_data->>'action','list')='detail' then
  if p_data->>'source_type'='past_exam' then if include_past then return public.quiz_learning_wrong_detail(p_data);else raise exception 'wrong_question_unavailable';end if;end if;
  if exists(select 1 from public.quiz_attempts a join public.quiz_learning_sessions ls on ls.session_id=a.session_id where a.id=(p_data->>'attempt_id')::uuid) then raise exception 'wrong_question_unavailable';end if;
  return public.quiz_wrong_questions_before_learning(p_data);
 end if;
 old:=public.quiz_wrong_questions_before_learning(p_data);if not exists(select 1 from public.quiz_learning_maps where enabled) and not exists(select 1 from public.quiz_learning_sessions) then return old;end if;
 with all_items as materialized(
  select jsonb_build_object('source_type','quiz','attempt_id',r.attempt_id,'session_id',r.session_id,'version_id',r.version_id,'question_id',r.question_id,'answered_at',r.answered_at,'title',r.title,'catalog',r.catalog,'number',array_position(r.ordered_ids,r.question_id),'preview',m.question_index->r.question_id->>'preview') item
  from public.quiz_wrong_refs((identity->>'grade')::integer) r join public.quiz_version_meta m on m.version_id=r.version_id where not exists(select 1 from public.quiz_learning_sessions ls where ls.session_id=r.session_id)
  union all select x from public.quiz_learning_wrong_items((identity->>'grade')::integer) x where include_past
 ),filtered as materialized(select item from all_items where (coalesce(p_data->>'subject','')='' or item->'catalog'->>'subject'=p_data->>'subject') and (coalesce(p_data->>'unit','')='' or coalesce(item->'catalog'->>'unit',item->>'title')=p_data->>'unit'))
 select (select count(*) from filtered),(select coalesce(jsonb_agg(item order by item->>'answered_at' desc,item->>'attempt_id',item->>'question_id'),'[]') from(select item from filtered order by item->>'answered_at' desc,item->>'attempt_id',item->>'question_id' limit 20 offset page*20) z),
 (select coalesce(jsonb_agg(f),'[]') from(select distinct jsonb_build_object('subject',coalesce(item->'catalog'->>'subject','未分類'),'unit',coalesce(item->'catalog'->>'unit',item->>'title')) f from all_items) x) into n,items,facets;
 return old||jsonb_build_object('items',items,'total',n,'facets',facets);
end$function$;
revoke all on function public.quiz_wrong_questions(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_wrong_questions(jsonb) to postgres;
grant execute on function public.quiz_wrong_questions(jsonb) to authenticated;
grant execute on function public.quiz_wrong_questions(jsonb) to service_role;

-- quiz_wrong_questions_before_learning(jsonb)  md5=561fa9e6da620c51a20752be34a8f8ca
CREATE OR REPLACE FUNCTION public.quiz_wrong_questions_before_learning(p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare identity jsonb; grade integer; page integer; subject text:=coalesce(p_data->>'subject','');unit text:=coalesce(p_data->>'unit','');
 r record; att public.quiz_attempts;sess public.quiz_sessions;b jsonb;q jsonb;options jsonb;response jsonb;source public.quiz_question_pool;v_course text;can_extend boolean:=false;result jsonb;
begin
 identity:=public.quiz_student_identity();grade:=(identity->>'grade')::integer;
 if coalesce(p_data->>'grade','') not in ('','3','4','6','9') or coalesce(p_data->>'page','0') !~ '^[0-9]{1,5}$' or length(subject)>30 or length(unit)>200 then raise exception 'invalid_request';end if;
 page:=coalesce((p_data->>'page')::integer,0);
 if coalesce(p_data->>'action','list')='detail' then
  if p_data->>'attempt_id' is null or p_data->>'question_id' is null then raise exception 'wrong_question_unavailable';end if;
  select * into r from public.quiz_wrong_refs(grade,p_data->>'attempt_id',p_data->>'question_id');
  if r.attempt_id is null then raise exception 'wrong_question_unavailable';end if;
  select * into sess from public.quiz_sessions where id=r.session_id;
  if sess.access_mode='self' and not exists(select 1 from public.quiz_generated_papers where session_id=sess.id and user_id=auth.uid()) then raise exception 'session_unavailable';end if;
  select * into att from public.quiz_attempts where id=r.attempt_id and user_id=auth.uid();
  -- List eligibility historically checks missing ids; resume disclosure additionally
  -- requires the exact answer count. Retain that distinction for malformed records.
  if sess.reveal='complete' and (select count(*) from public.quiz_answers where attempt_id=att.id)<>jsonb_array_length(att.question_order) then raise exception 'wrong_question_unavailable';end if;
  select bx,qx into b,q from public.quiz_versions v cross join lateral jsonb_array_elements(v.document->'blocks') bx
   cross join lateral jsonb_array_elements(bx->'questions') qx where v.id=r.version_id and qx->>'id'=r.question_id;
  if q is null or not(att.question_order ? r.question_id) then raise exception 'wrong_question_unavailable';end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',o->>'id','content',o->'content') order by ord),'[]') into options
   from jsonb_array_elements(coalesce(q->'options','[]')) o join jsonb_array_elements_text(coalesce(att.option_orders->r.question_id,'[]')) with ordinality x(id,ord) on o->>'id'=x.id;
  select x.response into response from public.quiz_answers x where x.attempt_id=att.id and x.question_id=r.question_id;
  source:=public.quiz_extension_source(r.version_id,r.question_id,r.catalog,grade);
  if source.question_id is not null then
   select coalesce(m.course_id,'115-1-hanlin-g3-math') into v_course from public.quiz_question_pool p left join public.quiz_pool_membership m on m.question_id=p.question_id where p.question_id=source.question_id;
   select exists(select 1 from public.quiz_question_pool p left join public.quiz_pool_membership m on m.question_id=p.question_id
    where p.usable and p.publisher_explanation and coalesce(m.knowledge_reliable,true) and coalesce(m.course_id,'115-1-hanlin-g3-math')=v_course
    and p.knowledge_code=source.knowledge_code and p.group_key<>source.group_key and p.difficulty<=source.difficulty) into can_extend;
  end if;
  return jsonb_build_object('attempt_id',r.attempt_id,'session_id',r.session_id,'version_id',r.version_id,'question_id',r.question_id,'answered_at',r.answered_at,
   'title',r.title,'catalog',r.catalog,'number',array_position(r.ordered_ids,r.question_id),'preview',left(q->'prompt'->>'text',160),'can_extend',can_extend,
   'question',jsonb_build_object('id',q->>'id','type',q->>'type','prompt',q->'prompt','block_id',b->>'id','material',b->'material','options',options),
   'review',jsonb_build_object('question_id',r.question_id,'answer',q->'answer','explanation',q->'explanation','correct',false),'response',response);
 end if;
 if coalesce(p_data->>'action','list')<>'list' then raise exception 'invalid_request';end if;
 with refs as materialized (select * from public.quiz_wrong_refs(grade)), filtered as materialized (
  select * from refs where (subject='' or coalesce(catalog->>'subject','未分類')=subject) and (unit='' or coalesce(catalog->>'unit',title)=unit)
 ), paged as (select * from filtered order by answered_at desc,attempt_id,question_id limit 20 offset page*20)
 select jsonb_build_object('role',identity->>'role','grade',grade,
  'facets',(select coalesce(jsonb_agg(f order by f->>'subject',f->>'unit'),'[]') from (select distinct jsonb_build_object('subject',coalesce(catalog->>'subject','未分類'),'unit',coalesce(catalog->>'unit',title)) f from refs) t),
  'total',(select count(*) from filtered),
  'items',(select coalesce(jsonb_agg(jsonb_build_object('attempt_id',p.attempt_id,'session_id',p.session_id,'question_id',p.question_id,'answered_at',p.answered_at,
   'title',p.title,'catalog',p.catalog,'number',array_position(p.ordered_ids,p.question_id),'preview',m.question_index->p.question_id->>'preview') order by p.answered_at desc,p.attempt_id,p.question_id),'[]')
   from paged p join public.quiz_version_meta m on m.version_id=p.version_id)) into result;
 return result;
end $function$;
revoke all on function public.quiz_wrong_questions_before_learning(jsonb) from public, anon, authenticated, service_role;
grant execute on function public.quiz_wrong_questions_before_learning(jsonb) to postgres;
grant execute on function public.quiz_wrong_questions_before_learning(jsonb) to service_role;

-- quiz_wrong_refs(integer,text,text)  md5=12c8cfd9c238bec82c27ee365839c0d9
CREATE OR REPLACE FUNCTION public.quiz_wrong_refs(p_grade integer, p_attempt text DEFAULT NULL::text, p_question text DEFAULT NULL::text)
 RETURNS TABLE(attempt_id uuid, session_id uuid, version_id uuid, question_id text, answered_at timestamp with time zone, title text, catalog jsonb, ordered_ids text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 with owned as materialized (
  select a.id,a.session_id,s.version_id,s.reveal,v.title,v.catalog,v.question_index,v.block_questions,
   array(select jsonb_array_elements_text(a.question_order)) ordered_ids
  from public.quiz_attempts a join public.quiz_sessions s on s.id=a.session_id
  join public.quiz_version_meta v on v.version_id=s.version_id
  where a.user_id=auth.uid() and (p_attempt is null or a.id=case when p_attempt ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p_attempt::uuid end) and s.access_mode<>'personal'
  and coalesce(nullif(left(v.catalog->>'volume',1),''),p_grade::text)=p_grade::text
  and exists(select 1 from public.student_enrollments e join auth.users u on lower(u.email)=e.email
   where u.id=auth.uid() and u.email_confirmed_at is not null and e.school_year=s.school_year and public.quiz_session_class_allowed(s.id,e.class_code))
 ), progress as materialized (
  select x.attempt_id,jsonb_object_agg(x.question_id,true) answered from public.quiz_answers x join owned a on a.id=x.attempt_id group by x.attempt_id
 )
 select a.id,a.session_id,a.version_id,x.question_id,x.created_at,a.title,a.catalog,a.ordered_ids
 from owned a join progress p on p.attempt_id=a.id join public.quiz_answers x on x.attempt_id=a.id and not x.correct
 where (p_question is null or x.question_id=p_question)
 and a.question_index ? x.question_id
 and ((a.reveal='complete' and p.answered ?& a.ordered_ids)
  or (a.reveal='immediate' and p.answered @> (a.block_questions->(a.question_index->x.question_id->>'block_id'))))
$function$;
revoke all on function public.quiz_wrong_refs(integer,text,text) from public, anon, authenticated, service_role;
grant execute on function public.quiz_wrong_refs(integer,text,text) to postgres;
grant execute on function public.quiz_wrong_refs(integer,text,text) to service_role;

-- reading_action(text,jsonb)  md5=ec306997350ed384911b6a544324458c
CREATE OR REPLACE FUNCTION public.reading_action(p_action text, p_data jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
 uid uuid:=auth.uid(); teacher boolean:=coalesce(public.is_teacher(),false); v_email text; target_email text; cls text;
 today date:=(now() at time zone 'Asia/Taipei')::date; p public.reading_periods;
 v public.reading_versions; s public.reading_submissions; target uuid; result jsonb;
 rid uuid; newstatus text; newfeedback text; firstdate date; lastdate date; wk text; deleted_versions integer;
begin
 if uid is null then raise exception 'login_required'; end if;
 select lower(u.email) into v_email from auth.users u where u.id=uid and u.email_confirmed_at is not null;
 if v_email is null then raise exception 'login_required'; end if;
 select e.class_code into cls from public.student_enrollments e where e.school_year=115 and e.email=v_email and e.class_code like '6%';
 if not teacher and cls is null then raise exception 'roster_required'; end if;
 if p_action='list' then
   select coalesce(jsonb_agg(to_jsonb(r)||jsonb_build_object('current',today between r.starts_on and r.ends_on,
    'submission',(select to_jsonb(v) from public.reading_submissions s join public.reading_versions v on v.id=s.version_id where s.period_id=r.id and s.user_id=uid)) order by r.week_code),'[]') into result
   from public.reading_periods r where (teacher and r.owner_user_id=uid) or
    (not teacher and r.starts_on<=today and (r.enabled or exists(select 1 from public.reading_submissions s where s.period_id=r.id and s.user_id=uid)));
   return jsonb_build_object('periods',result,'teacher',teacher,'today',today);
 end if;
 if p_action='configure' then
   if not teacher then raise exception 'teacher_required'; end if;
   perform pg_advisory_xact_lock(1156001);
   wk:=p_data->>'week_code';firstdate:=(p_data->>'starts_on')::date;lastdate:=(p_data->>'ends_on')::date;
   if wk is null or wk !~ '^(0[1-9]|1[0-9]|2[0-2])$' or firstdate is null or lastdate is null or
    firstdate < date '2026-08-01' or lastdate > date '2027-02-28' or lastdate<firstdate or lastdate-firstdate>6 then raise exception 'invalid_period'; end if;
   select * into p from public.reading_periods where course_id='grade6-115-1' and week_code=wk for update;
   if p.id is not null then
    if p.owner_user_id<>uid then raise exception 'teacher_required'; end if;
    if exists(select 1 from public.reading_submissions where period_id=p.id) and (p.starts_on<>firstdate or p.ends_on<>lastdate) then raise exception 'period_has_submissions'; end if;
   end if;
   if exists(select 1 from public.reading_periods r where r.week_code<>wk and r.starts_on<=lastdate and r.ends_on>=firstdate) then raise exception 'period_overlap'; end if;
   insert into public.reading_periods(owner_user_id,week_code,starts_on,ends_on,enabled) values(uid,wk,firstdate,lastdate,coalesce((p_data->>'enabled')::boolean,true))
    on conflict(course_id,week_code) do update set starts_on=excluded.starts_on,ends_on=excluded.ends_on,enabled=excluded.enabled;
   return jsonb_build_object('ok',true);
 end if;
 select * into p from public.reading_periods where id=(p_data->>'period_id')::uuid for update;
 if p.id is null or (teacher and p.owner_user_id<>uid) or (not teacher and p.starts_on>today) then raise exception 'period_unavailable'; end if;
 if p_action='roster' then
   if not teacher then raise exception 'teacher_required'; end if;
   select coalesce(jsonb_agg(to_jsonb(v)||jsonb_build_object('display_name',e.display_name,'seat_no',e.seat_no,'class_code',e.class_code,
    'is_test_account',lower(u.email)='chianwu@apps.ntpc.edu.tw','version_count',(select count(*) from public.reading_versions h where h.period_id=p.id and h.user_id=s.user_id)) order by e.class_code,e.seat_no),'[]') into result
    from public.reading_submissions s join public.reading_versions v on v.id=s.version_id join auth.users u on u.id=s.user_id
    join public.student_enrollments e on e.email=lower(u.email) and e.school_year=115 and e.class_code like '6%'
    where s.period_id=p.id;
   return jsonb_build_object('students',result);
 end if;
 target:=case when teacher then (p_data->>'user_id')::uuid else uid end;
 if target is null then raise exception 'invalid_request'; end if;
 select * into s from public.reading_submissions where period_id=p.id and user_id=target for update;
 if p_action='reset_test_submission' then
   if not teacher then raise exception 'teacher_required'; end if;
   select lower(u.email) into target_email from auth.users u where u.id=target and u.email_confirmed_at is not null;
   if target_email is distinct from 'chianwu@apps.ntpc.edu.tw' then raise exception 'test_account_required'; end if;
   select count(*) into deleted_versions from public.reading_versions v where v.period_id=p.id and v.user_id=target;
   if deleted_versions=0 then raise exception 'test_submission_missing'; end if;
   delete from public.reading_events e where e.version_id in (select v.id from public.reading_versions v where v.period_id=p.id and v.user_id=target);
   delete from public.reading_submissions s where s.period_id=p.id and s.user_id=target;
   delete from public.reading_versions v where v.period_id=p.id and v.user_id=target;
   insert into public.reading_test_resets(period_id,student_user_id,actor_user_id,versions_deleted) values(p.id,target,uid,deleted_versions);
   return jsonb_build_object('ok',true,'versions_deleted',deleted_versions);
 end if;
 if p_action='history' then
   if not teacher and not p.enabled and s.version_id is null then raise exception 'period_unavailable'; end if;
   select coalesce(jsonb_agg(to_jsonb(v)||jsonb_build_object('latest',v.id=s.version_id) order by v.submitted_at desc,v.id),'[]') into result from public.reading_versions v where v.period_id=p.id and v.user_id=target;
   return jsonb_build_object('versions',result);
 end if;
 if p_action='submit' then
   if teacher then raise exception 'student_required'; end if;
   if not p.enabled then raise exception 'period_unavailable'; end if;
   rid:=(p_data->>'id')::uuid;
   if rid is null then raise exception 'invalid_request'; end if;
   select * into v from public.reading_versions where id=rid;
   if v.id is not null then
    if v.user_id<>uid or v.period_id<>p.id or v.source is distinct from p_data->>'source' or v.book is distinct from trim(p_data->>'book') or v.reflection is distinct from trim(p_data->>'reflection') then raise exception 'submission_conflict'; end if;
    return jsonb_build_object('ok',true,'id',v.id);
   end if;
   if s.version_id is distinct from (p_data->>'expected_version')::uuid then raise exception 'version_changed'; end if;
   insert into public.reading_versions(id,period_id,user_id,source,book,reflection) values(rid,p.id,uid,p_data->>'source',trim(p_data->>'book'),trim(p_data->>'reflection'));
   insert into public.reading_submissions(period_id,user_id,version_id) values(p.id,uid,rid) on conflict(period_id,user_id) do update set version_id=excluded.version_id;
   insert into public.reading_events(version_id,actor_id,event) values(rid,uid,'submitted');
   return jsonb_build_object('ok',true,'id',rid);
 end if;
 if p_action='review' then
   if not teacher then raise exception 'teacher_required'; end if;
   if s.version_id is null or s.version_id is distinct from (p_data->>'version_id')::uuid then raise exception 'version_changed'; end if;
   select * into v from public.reading_versions where id=s.version_id for update;
   if v.review_seq is distinct from (p_data->>'review_seq')::integer then raise exception 'review_changed'; end if;
   newstatus:=coalesce(p_data->>'status',v.status);newfeedback:=coalesce(p_data->>'feedback',v.feedback);
   if newstatus not in ('submitted','passed','needs_revision') or length(newfeedback)>2000 then raise exception 'invalid_review'; end if;
   if newstatus<>v.status or newfeedback<>v.feedback then
    update public.reading_versions set status=newstatus,feedback=newfeedback,review_seq=review_seq+1,reviewed_at=case when newstatus='submitted' then null else now() end where id=v.id;
    insert into public.reading_events(version_id,actor_id,event,feedback) values(v.id,uid,newstatus,newfeedback);
   end if;
   return jsonb_build_object('ok',true);
 end if;
 raise exception 'invalid_action';
end $function$;
revoke all on function public.reading_action(text,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.reading_action(text,jsonb) to postgres;
grant execute on function public.reading_action(text,jsonb) to authenticated;
grant execute on function public.reading_action(text,jsonb) to service_role;

-- reconnect_grade3_progress()  md5=375a48402c87e545abe382074cee2a65
CREATE OR REPLACE FUNCTION public.reconnect_grade3_progress()
 RETURNS TABLE(class_code text, seat_no smallint, display_name text, student_code text, practice_account text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e record; g record; a record; old_binding record; approval record; s integer; t integer; c text;
begin
 if auth.uid() is null then raise exception '請先登入 Google。'; end if;
 select en.*, cs.practice_account into e
 from public.student_enrollments en join auth.users u on u.id=auth.uid()
   and u.email_confirmed_at is not null and lower(u.email)=en.email
 join public.class_card_students cs on cs.course_id='grade3-115-1'
   and cs.class_code=en.class_code and cs.seat_no=en.seat_no and cs.active
   and trim(cs.display_name)=trim(en.display_name)
   and lower(cs.practice_account || '@apps.ntpc.edu.tw')=en.email
 where en.school_year=115 and en.class_code in ('301','302','303','304','305','306','307');
 if not found then raise exception '學校帳號與三年級名冊不一致，請找老師。'; end if;
 c:=e.class_code || lpad(e.seat_no::text,2,'0');
 perform pg_advisory_xact_lock(hashtextextended('grade3-google:' || c,0));
 if exists(select 1 from public.grade3_google_bindings b where b.user_id=auth.uid() and b.student_code<>c) then
   raise exception '班級座號已異動，請老師查核原綁定，不能重新認領。';
 end if;
 select * into approval from public.grade3_google_approvals ga where ga.email=e.email and ga.student_code=c and trim(ga.display_name)=trim(e.display_name);
 if not found then raise exception '老師尚未核對你的歷史名冊，舊成果尚未接回，請找老師。'; end if;
 perform pg_advisory_xact_lock(hashtextextended('grade3-history:' || approval.history_student_code,0));
 if exists(select 1 from public.grade3_google_bindings b where b.history_student_code=approval.history_student_code and b.user_id<>auth.uid()) then
   raise exception '歷史成果已有其他帳號綁定，請找老師查核。';
 end if;
 select * into old_binding from public.grade3_google_bindings b where b.student_code=c;
 if found then
   if old_binding.user_id<>auth.uid() or old_binding.email<>e.email or old_binding.history_student_code<>approval.history_student_code then raise exception '帳號綁定衝突，請找老師。'; end if;
 else
   for g in select * from public.student_progress p where p.course_id='grade3-115-1' and p.user_id=auth.uid() loop
     select * into a from public.grade3_google_activities ga where ga.week_code=g.week_code and ga.activity_key=g.activity_key;
     -- Legacy Google typing wrote completed/current_level without a score.
     -- Accept that shape only when the teacher approved the exact original row.
     s:=case when g.activity_key like 'typing_%' and g.score is null and g.completed and g.current_level=a.total then a.total else coalesce(g.score,g.current_level-1) end;
     if not found or g.current_level is null or g.completed is null
        or g.current_level not between 1 and a.total or g.score not between 0 and a.total
        or g.completed is distinct from (s=a.total)
        or g.current_level<>least(s+1,a.total)
        or not (approval.reviewed_existing_progress @> jsonb_build_array(to_jsonb(g))) then
       raise exception '先前正式成果尚未經老師核對，請找老師。';
     end if;
   end loop;
   -- Validate the complete source snapshot before any import, including unknown activities.
   for g in select * from public.guest_progress gp where gp.course_id='grade3-115-1' and gp.student_code=approval.history_student_code loop
     select * into a from public.grade3_google_activities ga where ga.week_code=g.week_code and ga.activity_key=g.activity_key;
     if not found or g.week_code='06' or g.current_level is null or g.completed is null
       or g.current_level<1 or g.current_level>a.total
       or (g.score is not null and (g.score<0 or g.score>a.total))
       or g.completed is distinct from (coalesce(g.score,g.current_level-1)=a.total)
       or g.current_level<>least(coalesce(g.score,g.current_level-1)+1,a.total)
       or (g.class_code || lpad(g.seat_no::text,2,'0')) is distinct from approval.history_student_code or trim(g.display_name) is distinct from trim(approval.history_display_name) then
       raise exception '舊成果資料需老師查核，尚未接回。';
     end if;
   end loop;
   update public.student_progress p set score=case when p.completed then ga.total else p.current_level-1 end
     from public.grade3_google_activities ga where p.user_id=auth.uid() and p.course_id='grade3-115-1'
       and p.week_code=ga.week_code and p.activity_key=ga.activity_key and p.score is null;
   insert into public.grade3_google_bindings(student_code,history_student_code,user_id,email) values(c,approval.history_student_code,auth.uid(),e.email);
   for g in select * from public.guest_progress gp where gp.course_id='grade3-115-1' and gp.student_code=approval.history_student_code loop
     select ga.total into t from public.grade3_google_activities ga where ga.week_code=g.week_code and ga.activity_key=g.activity_key;
     s:=case when g.completed then t else coalesce(g.score,g.current_level-1) end;
     insert into public.grade3_google_imports(student_code,week_code,activity_key,user_id,source_snapshot)
       values(approval.history_student_code,g.week_code,g.activity_key,auth.uid(),to_jsonb(g));
     insert into public.student_progress as p(user_id,course_id,week_code,activity_key,current_level,score,completed,updated_at)
       values(auth.uid(),'grade3-115-1',g.week_code,g.activity_key,least(s+1,t),s,s=t,g.updated_at)
       on conflict(user_id,course_id,week_code,activity_key) do update set
         completed=p.completed or excluded.completed,
         score=case when p.completed or excluded.completed then t else greatest(coalesce(p.score,p.current_level-1),excluded.score) end,
         current_level=case when p.completed or excluded.completed then t else least(greatest(p.current_level,excluded.current_level),t) end,
         updated_at=greatest(p.updated_at,excluded.updated_at);
   end loop;
 end if;
 return query select e.class_code::text,e.seat_no::smallint,e.display_name::text,c,e.practice_account::text;
exception when unique_violation then
 raise exception '資料綁定或匯入紀錄衝突，請找老師查核。';
end $function$;
revoke all on function public.reconnect_grade3_progress() from public, anon, authenticated, service_role;
grant execute on function public.reconnect_grade3_progress() to postgres;
grant execute on function public.reconnect_grade3_progress() to authenticated;
grant execute on function public.reconnect_grade3_progress() to service_role;

-- refresh_student_code(text,smallint)  md5=cf467695a29c54b0fda081090b878b53
CREATE OR REPLACE FUNCTION public.refresh_student_code(p_class_code text, p_seat_no smallint)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
    select
        case
            when p_class_code is null or p_seat_no is null then null
            else p_class_code || lpad(p_seat_no::text, 2, '0')
        end;
$function$;
