-- partner_pilot.register_self()  md5=38ed977b2ca39d46bf998afd312eb291
CREATE OR REPLACE FUNCTION partner_pilot.register_self()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare label text;
begin
 if not partner_pilot.can_access() then raise exception 'ACCESS_DENIED';end if;
 select e.class_code||'班'||e.seat_no||'號 '||e.display_name into strict label from auth.users u join public.student_enrollments e on e.email=lower(u.email) and e.school_year=115 where u.id=auth.uid();
 insert into partner_pilot.allowed_users(user_id,display_name) values(auth.uid(),label) on conflict(user_id) do update set display_name=excluded.display_name,active=true where partner_pilot.allowed_users.display_name is distinct from excluded.display_name or not partner_pilot.allowed_users.active;
end $function$;
revoke all on function partner_pilot.register_self() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.register_self() to postgres;

-- rls_auto_enable()  md5=6998ea6b4c2480f5d2e34b5dcf3f8d36
CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;
revoke all on function public.rls_auto_enable() from public, anon, authenticated, service_role;
grant execute on function public.rls_auto_enable() to public;
grant execute on function public.rls_auto_enable() to postgres;
grant execute on function public.rls_auto_enable() to anon;
grant execute on function public.rls_auto_enable() to authenticated;
grant execute on function public.rls_auto_enable() to service_role;

-- save_grade3_progress(text,text,integer)  md5=7fac40ce9989a51cf2033f897385beb2
CREATE OR REPLACE FUNCTION public.save_grade3_progress(p_week_code text, p_activity_key text, p_score integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t integer;
begin
 if not public.grade3_google_ready() then raise exception '請先接回本人舊成果。'; end if;
 select total into t from public.grade3_google_activities where week_code=p_week_code and activity_key=p_activity_key;
 if t is null or p_score is null or p_score<0 or p_score>t then raise exception '無效的活動進度。'; end if;
 insert into public.student_progress as p(user_id,course_id,week_code,activity_key,current_level,score,completed)
 values(auth.uid(),'grade3-115-1',p_week_code,p_activity_key,least(p_score+1,t),p_score,p_score=t)
 on conflict(user_id,course_id,week_code,activity_key) do update set
   score=case when p.completed or excluded.completed then t else greatest(coalesce(p.score,p.current_level-1),excluded.score) end,
   completed=p.completed or excluded.completed,current_level=greatest(p.current_level,excluded.current_level),updated_at=now();
end $function$;
revoke all on function public.save_grade3_progress(text,text,integer) from public, anon, authenticated, service_role;
grant execute on function public.save_grade3_progress(text,text,integer) to postgres;
grant execute on function public.save_grade3_progress(text,text,integer) to authenticated;
grant execute on function public.save_grade3_progress(text,text,integer) to service_role;

-- partner_pilot.self_catalog()  md5=74d6abe07590863cedfabafe8d251956
CREATE OR REPLACE FUNCTION partner_pilot.self_catalog()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce(jsonb_agg(jsonb_build_object('id','self:'||s.id,'title',coalesce(g.display_name,v.document->>'title'),
 'grade',left(e.class_code,1)::int,'subject',v.document#>>'{catalog,subject}','kind','leaf','self',true,
 'total',(select count(*) from jsonb_array_elements(v.document->'blocks') b cross join lateral jsonb_array_elements(b->'questions') q),
 'real',true,'past',false,'sourceSession',s.id,'sourceSessions',jsonb_build_array(s.id)) order by g.created_at desc,s.id),'[]')
 from public.quiz_generated_papers g join public.quiz_sessions s on s.id=g.session_id
 join public.quiz_versions v on v.id=s.version_id join auth.users u on u.id=auth.uid()
 join public.student_enrollments e on e.email=lower(u.email) and e.school_year=115
 where g.user_id=auth.uid() and s.owner_id=auth.uid() and g.deleted_at is null and g.config->>'kind'='self'
 and g.config->>'count' in ('10','20') and s.access_mode='self' and s.status='open' and s.school_year=115
 and s.class_codes ? e.class_code and partner_pilot.self_document_ok(v.document)
$function$;
revoke all on function partner_pilot.self_catalog() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.self_catalog() to postgres;

-- partner_pilot.self_document_ok(jsonb)  md5=915ff31ec471fde42f9781da15f04400
CREATE OR REPLACE FUNCTION partner_pilot.self_document_ok(doc jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select (select count(*) from jsonb_array_elements(doc->'blocks') b cross join lateral jsonb_array_elements(b->'questions') q) in (10,20)
 and not exists(select 1 from jsonb_array_elements(doc->'blocks') b where jsonb_array_length(b->'questions')<>1)
 and not exists(select 1 from jsonb_array_elements(doc->'blocks') b cross join lateral jsonb_array_elements(b->'questions') q where q->>'type' is distinct from 'single')
$function$;
revoke all on function partner_pilot.self_document_ok(jsonb) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.self_document_ok(jsonb) to postgres;

-- partner_pilot.snapshot(uuid)  md5=ab32e534bb561362cef923c58a1bd77e
CREATE OR REPLACE FUNCTION partner_pilot.snapshot(rid uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'partner_pilot'
AS $function$
declare r partner_pilot.rooms; answer jsonb;
begin
 if not exists(select 1 from partner_pilot.members where room_id=rid and user_id=auth.uid()) then raise exception 'NOT_MEMBER'; end if;
 select * into strict r from partner_pilot.rooms where id=rid;
 select jsonb_build_object('id',r.id,'code',r.code,'team',r.team,'theme',r.theme,'paper',r.paper,'capacity',r.capacity,'host',r.host,'revision',r.revision,'started',r.started,'allocationVersion',r.allocation_version,'topic','partner-pilot:'||r.id||':'||r.epoch,'members',coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',u.display_name,'ready',m.ready,'character',(case r.theme when 'space' then array['星星','月亮','彗星','太陽'] when 'dora' then array['大雄','哆啦A夢','靜香','小夫'] else array['小鹿','松鼠','狐狸','貓頭鷹'] end)[((m.position::int+r.character_offset-1)%4)+1])),'[]'::jsonb),'questions',case when r.started then (select coalesce(jsonb_agg(i.number order by i.number),'[]'::jsonb) from partner_pilot.paper_items i where i.paper_id=r.paper and partner_pilot.owner_of(rid,i.qid)=auth.uid()) else '[]'::jsonb end) into answer
 from (select *,row_number() over(order by joined_at,user_id) position from partner_pilot.members where room_id=rid) m join partner_pilot.allowed_users u using(user_id);
 return answer;
end $function$;
revoke all on function partner_pilot.snapshot(uuid) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.snapshot(uuid) to postgres;

-- partner_pilot.source_allowed(text,boolean)  md5=26bb60da71915052db82c85e533fbef7
CREATE OR REPLACE FUNCTION partner_pilot.source_allowed(pid text, continuing boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select exists(select 1 from partner_pilot.papers p join auth.users u on u.id=auth.uid() join public.student_enrollments e on e.email=lower(u.email) and e.school_year=115 where p.id=pid and p.enabled and p.is_real and left(e.class_code,1)=p.grade::text and case when p.origin='self' then p.total in (10,20) and exists(select 1 from partner_pilot.rooms r join partner_pilot.members m on m.room_id=r.id where r.paper=p.id and m.user_id=auth.uid()) when p.past_meta is not null then exists(select 1 from public.quiz_past_papers s where s.id=p.past_meta->>'sourcePaper' and s.enabled and s.grade=p.grade and (continuing or exists(select 1 from partner_pilot.allocation_specs a where a.version=p.source_version)) and (continuing or s.active_version=p.source_version)) else p.total in (10,20) and exists(select 1 from partner_pilot.paper_sources ps join public.quiz_sessions s on s.id=ps.session_id where ps.paper_id=p.id and s.status='open' and s.library_visible and s.access_mode='practice' and s.school_year=115 and public.quiz_session_class_allowed(s.id,e.class_code) and (continuing or s.version_id=p.source_version)) end)
$function$;
revoke all on function partner_pilot.source_allowed(text,boolean) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.source_allowed(text,boolean) to postgres;

-- partner_pilot.source_available(text)  md5=5dcb5ecb6009a046df875a5def8bf8cd
CREATE OR REPLACE FUNCTION partner_pilot.source_available(pid text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$ select partner_pilot.source_allowed(pid,true) $function$;
revoke all on function partner_pilot.source_available(text) from public, anon, authenticated, service_role;
grant execute on function partner_pilot.source_available(text) to postgres;

-- student_profiles_set_defaults()  md5=7c268b8d5616bdc7d1c9b7841f46feb3
CREATE OR REPLACE FUNCTION public.student_profiles_set_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
    if new.email is null then
        select au.email::text
        into new.email
        from auth.users au
        where au.id = new.user_id;
    end if;

    new.student_code := public.refresh_student_code(new.class_code, new.seat_no);
    new.updated_at := now();
    return new;
end;
$function$;
revoke all on function public.student_profiles_set_defaults() from public, anon, authenticated, service_role;
grant execute on function public.student_profiles_set_defaults() to public;
grant execute on function public.student_profiles_set_defaults() to postgres;
grant execute on function public.student_profiles_set_defaults() to anon;
grant execute on function public.student_profiles_set_defaults() to authenticated;
grant execute on function public.student_profiles_set_defaults() to service_role;

-- switch_test_identity(text)  md5=ff4a40f65e7236d148a0d3ef28b348cf
CREATE OR REPLACE FUNCTION public.switch_test_identity(p_grade text DEFAULT NULL::text)
 RETURNS TABLE(class_code text, seat_no smallint, display_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare mail constant text:='chianwu@apps.ntpc.edu.tw'; n integer; target_class text; target_name text;
begin
 if auth.uid() is null or not exists(select 1 from auth.users u
  where u.id=auth.uid() and u.email_confirmed_at is not null and lower(u.email)=mail) then
  raise exception 'not_test_account' using errcode='42501';
 end if;
 if p_grade is not null then
  if p_grade='grade3' then
   target_class:='307';
   select trim(c.display_name) into target_name from public.class_card_students c
    where c.course_id='grade3-115-1' and c.class_code='307' and c.seat_no=30 and c.active;
  elsif p_grade='grade4' then target_class:='407';target_name:=U&'\5433\5C0F\8B19';
  elsif p_grade='grade6' then target_class:='609';target_name:=U&'\5433\5C0F\8B19';
  elsif p_grade='grade9' then target_class:='922';target_name:=U&'\5433\5C0F\8B19';
  else raise exception 'invalid_grade';end if;
  if target_name is null then raise exception 'test_identity_not_ready';end if;
  update public.student_enrollments e set class_code=target_class,display_name=target_name
   where e.school_year=115 and e.email=mail and e.seat_no=30 and e.class_code in('307','407','609','922');
  get diagnostics n=row_count;
  if n<>1 then raise exception 'test_identity_not_ready';end if;
 end if;
 return query select e.class_code::text,e.seat_no::smallint,e.display_name::text
  from public.student_enrollments e where e.school_year=115 and e.email=mail;
end $function$;
revoke all on function public.switch_test_identity(text) from public, anon, authenticated, service_role;
grant execute on function public.switch_test_identity(text) to postgres;
grant execute on function public.switch_test_identity(text) to authenticated;
grant execute on function public.switch_test_identity(text) to service_role;

-- partner_pilot.sync_source_links()  md5=ca8e407b2b5d93ae4b011c5d615c7149
CREATE OR REPLACE FUNCTION partner_pilot.sync_source_links()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select pg_advisory_xact_lock(hashtextextended('partner-match-source-links',0));
 insert into partner_pilot.paper_sources select p.id,s.id from partner_pilot.papers p join public.quiz_sessions s on s.version_id=p.source_version
 where p.past_meta is null and s.access_mode='practice' and s.status='open' and s.library_visible and s.school_year=115
 and not exists(select 1 from public.quiz_generated_papers g where g.session_id=s.id) order by p.id,s.id on conflict do nothing
$function$;
revoke all on function partner_pilot.sync_source_links() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.sync_source_links() to postgres;

-- partner_pilot.team_rooms()  md5=4d86f90d9ee87ec31dff42e3b94480e3
CREATE OR REPLACE FUNCTION partner_pilot.team_rooms()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select coalesce(jsonb_agg(jsonb_build_object(
  'id',r.id,'team',r.team,'started',r.started,'finished',r.finished,'capacity',r.capacity,'host',r.host,
  'title',p.title,'subject',p.subject,'total',p.total,'kind',p.kind,
  'paused',not partner_pilot.source_allowed(r.paper,r.started),
  'inviteExpired',not r.started and r.expires_at<=now(),
  'count',(select count(*) from partner_pilot.members m where m.room_id=r.id),
  'members',(select coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',u.display_name,
   'assigned',case when r.started then (select count(*) from partner_pilot.paper_items i where i.paper_id=r.paper and partner_pilot.owner_of(r.id,i.qid)=m.user_id) else 0 end,
   'submitted',(select count(distinct a.qid) from partner_pilot.answers a where a.room_id=r.id and a.user_id=m.user_id),
   'reviewed',exists(select 1 from partner_pilot.review_seen v where v.room_id=r.id and v.user_id=m.user_id)) order by m.joined_at,m.user_id),'[]')
   from partner_pilot.members m join partner_pilot.allowed_users u on u.user_id=m.user_id where m.room_id=r.id),
  'phase',case when r.finished then 'completed' when not r.started then 'waiting'
   when s.submitted=s.total then 'review' else 'practice' end,
  'progress',jsonb_build_object('total',s.total,'submitted',s.submitted,'graded',s.graded,
   'correct',case when s.submitted=s.total and r.started then s.correct else null end,
   'reviewed',(select count(*) from partner_pilot.review_seen v where v.room_id=r.id),
   'meReviewed',exists(select 1 from partner_pilot.review_seen v where v.room_id=r.id and v.user_id=auth.uid()),
   'award',(select jsonb_build_object('leaves',a.leaves,'flowers',a.flowers,'earnedHere',a.room_id=r.id)
     from partner_pilot.awards a where a.content_key=p.content_key and a.member_key=(select string_agg(user_id::text,',' order by user_id) from partner_pilot.members where room_id=r.id)))
 ) order by r.created_at desc,r.id),'[]'::jsonb)
 from partner_pilot.rooms r join partner_pilot.members mine on mine.room_id=r.id and mine.user_id=auth.uid() join partner_pilot.papers p on p.id=r.paper
 cross join lateral (select partner_pilot.paper_total(r.paper) total,
  (select count(distinct a.qid) from partner_pilot.answers a where a.room_id=r.id) submitted,
  (select count(*) from partner_pilot.paper_items i join partner_pilot.question_bank q on q.id=i.qid where i.paper_id=r.paper and coalesce(q.past_meta->>'selfCheck','false')<>'true') graded,
  (select count(*) from (select distinct on(a.qid) a.correct from partner_pilot.answers a where a.room_id=r.id order by a.qid,a.attempt desc)x where correct) correct) s
$function$;
revoke all on function partner_pilot.team_rooms() from public, anon, authenticated, service_role;
grant execute on function partner_pilot.team_rooms() to postgres;

-- typing_foundation_action(text,text,jsonb)  md5=6b30bf5be692c56baae9e057fa4ecd63
CREATE OR REPLACE FUNCTION public.typing_foundation_action(p_action text, p_course_id text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  learner text; label text; r public.typing_foundation_progress%rowtype;
  stage_no integer; correct_no integer; error_no integer; ms numeric;
  acc numeric; speed numeric; target numeric; passed boolean; interrupted boolean;
  session_id uuid; event_id uuid; fingerprint text; out_rows jsonb;
  lesson text := coalesce(p_payload->>'lesson_key','english-home-row-v1');
  curriculum public.typing_foundation_lessons%rowtype;
begin
  if p_course_id is null or p_course_id not in ('grade3-115-1','grade6-115-1') then raise exception 'invalid_course'; end if;
  if p_action in ('admin_list','admin_reset') then
    if not public.is_teacher() then raise exception 'teacher_required'; end if;
    if p_action='admin_list' then
      select coalesce(jsonb_agg(to_jsonb(x) order by x.learner_key),'[]'::jsonb) into out_rows
      from (select p.*,
        l.rate_unit,
        (select max(coalesce(e.cpm,e.wpm)) from public.typing_foundation_events e where e.progress_id=p.id and e.revision=p.revision and e.stage=6 and e.passed) as best_rate,
        (select max(e.wpm) from public.typing_foundation_events e where e.progress_id=p.id and e.revision=p.revision and e.stage=6 and e.passed) as best_wpm,
        (select max(e.accuracy) from public.typing_foundation_events e where e.progress_id=p.id and e.revision=p.revision and e.stage=6 and e.passed) as best_accuracy
        from public.typing_foundation_progress p join public.typing_foundation_lessons l on l.lesson_key=p.lesson_key
        where p.course_id=p_course_id and (l.track='english' or coalesce((p_payload->>'include_zhuyin')::boolean,false))) x;
      return out_rows;
    end if;
    select * into r from public.typing_foundation_progress p where p.id=(p_payload->>'id')::uuid and p.course_id=p_course_id;
    if not found then raise exception 'progress_not_found'; end if;
    perform pg_advisory_xact_lock(hashtextextended(p_course_id||r.learner_key,0));
    select * into r from public.typing_foundation_progress p where p.id=r.id for update;
    if r.revision is distinct from (p_payload->>'revision')::integer then raise exception 'stale_revision'; end if;
    insert into public.typing_foundation_resets(progress_id,teacher_id,previous_revision,previous_checkpoint,previous_completed)
      values(r.id,auth.uid(),r.revision,r.checkpoint,r.completed);
    update public.typing_foundation_progress set checkpoint=0,completed=false,completed_at=null,starter=false,
      revision=revision+1,pending_count=0,pending_fingerprint=null,practice_session=null,updated_at=now() where id=r.id returning * into r;
    return to_jsonb(r);
  end if;
  if p_action is null or p_action not in ('list','load','start','save') then raise exception 'invalid_action'; end if;
    if auth.uid() is null or public.is_teacher() then raise exception 'student_required'; end if;
    if p_course_id='grade3-115-1' and not public.grade3_google_ready() then raise exception 'course_identity_required'; end if;
    select 'google:'||u.id::text,e.display_name into learner,label from auth.users u
      join public.student_enrollments e on e.email=lower(u.email) and e.school_year=115
        and ((p_course_id='grade3-115-1' and e.class_code in ('301','302','303','304','305','306','307'))
          or (p_course_id='grade6-115-1' and e.class_code like '6%'))
      where u.id=auth.uid();
    if learner is null then raise exception 'roster_required'; end if;
  perform pg_advisory_xact_lock(hashtextextended(p_course_id||learner,0));
  if p_action='list' then
   select coalesce(jsonb_agg(to_jsonb(p)),'[]'::jsonb) into out_rows from public.typing_foundation_progress p where p.course_id=p_course_id and p.learner_key=learner
    and (coalesce((p_payload->>'include_zhuyin')::boolean,false) or (p.lesson_key like 'zhuyin-%')=(lesson like 'zhuyin-%'));
   return out_rows;
  end if;
  select * into curriculum from public.typing_foundation_lessons where lesson_key=lesson;
  if not found then raise exception 'invalid_lesson'; end if;
  if exists(select 1 from public.typing_foundation_lessons l where l.track=curriculum.track and l.ordinal<curriculum.ordinal and not exists(
   select 1 from public.typing_foundation_progress p where p.course_id=p_course_id and p.learner_key=learner and p.lesson_key=l.lesson_key and p.completed)) then raise exception 'lesson_locked'; end if;
  select * into r from public.typing_foundation_progress p where p.course_id=p_course_id and p.learner_key=learner and p.lesson_key=lesson for update;
  if p_action='load' then return case when r.id is null then 'null'::jsonb else to_jsonb(r) end; end if;
  session_id := (p_payload->>'session_id')::uuid;
  if session_id is null then raise exception 'session_required'; end if;
  if p_action='start' then
    insert into public.typing_foundation_progress(course_id,learner_key,display_name,lesson_key,starter,practice_session)
      values(p_course_id,learner,label,lesson,p_course_id='grade6-115-1' and coalesce((p_payload->>'starter')::boolean,false),session_id)
      on conflict(course_id,learner_key,lesson_key) do nothing;
    select * into r from public.typing_foundation_progress p where p.course_id=p_course_id and p.learner_key=learner and p.lesson_key=lesson for update;
    if r.checkpoint=0 and not r.completed then
      update public.typing_foundation_progress set starter=p_course_id='grade6-115-1' and coalesce((p_payload->>'starter')::boolean,false) where id=r.id;
    end if;
    update public.typing_foundation_progress set practice_session=session_id,pending_count=0,pending_fingerprint=null where id=r.id returning * into r;
    return to_jsonb(r);
  end if;
  if r.id is null then raise exception 'start_required'; end if;
  if (p_payload->>'revision')::integer is distinct from r.revision then raise exception 'stale_revision'; end if;
  if session_id is distinct from r.practice_session then raise exception 'session_changed'; end if;
  event_id := (p_payload->>'event_id')::uuid;
  if event_id is null then raise exception 'event_required'; end if;
  if exists(select 1 from public.typing_foundation_events e where e.id=event_id and e.progress_id=r.id and e.revision=r.revision) then return to_jsonb(r); end if;
  stage_no := (p_payload->>'stage')::integer; correct_no := (p_payload->>'correct')::integer;
  error_no := (p_payload->>'errors')::integer; ms := (p_payload->>'elapsed_ms')::numeric;
  interrupted := (p_payload->>'interrupted')::boolean; fingerprint := p_payload->>'fingerprint';
  if stage_no is null or stage_no not between 1 and 6 or stage_no>r.checkpoint+1
    or correct_no is distinct from curriculum.counts[stage_no]
    or error_no is null or error_no not between 0 and 100000 or ms is null or ms::text in ('NaN','Infinity','-Infinity') or ms<=0 or ms>86400000
    or interrupted is null or fingerprint is null or length(fingerprint) not between 16 and 128 then raise exception 'invalid_attempt'; end if;
  acc := correct_no::numeric/(correct_no+error_no)*100;
  speed := correct_no::numeric*12000/ms;
  target := case when p_course_id='grade6-115-1' and not r.starter then curriculum.speed else curriculum.starter_speed end;
  passed := case when stage_no=6 then acc>=95 and (curriculum.track='zhuyin' or (speed>=target and not interrupted)) else acc>=90 end;
  insert into public.typing_foundation_events(id,progress_id,revision,stage,correct,errors,elapsed_ms,interrupted,accuracy,wpm,passed)
    values(event_id,r.id,r.revision,stage_no,correct_no,error_no,ms,interrupted,acc,case when curriculum.track='english' then speed else 0 end,passed);
  if curriculum.track='zhuyin' then update public.typing_foundation_events set cpm=correct_no::numeric*60000/ms,rate_unit=curriculum.rate_unit where id=event_id;end if;
  if stage_no<6 and passed then
    update public.typing_foundation_progress set checkpoint=greatest(checkpoint,stage_no),updated_at=now() where id=r.id;
  elsif stage_no=6 then
    if passed and r.pending_count=1 and r.pending_fingerprint<>fingerprint then
      update public.typing_foundation_progress set completed=true,completed_at=coalesce(completed_at,now()),pending_count=0,pending_fingerprint=null,updated_at=now() where id=r.id;
    else
      update public.typing_foundation_progress set pending_count=case when passed then 1 else 0 end,
        pending_fingerprint=case when passed then fingerprint else null end,updated_at=now() where id=r.id;
    end if;
  end if;
  select * into r from public.typing_foundation_progress p where p.id=r.id;
  return to_jsonb(r);
end; $function$;
revoke all on function public.typing_foundation_action(text,text,jsonb) from public, anon, authenticated, service_role;
grant execute on function public.typing_foundation_action(text,text,jsonb) to postgres;
grant execute on function public.typing_foundation_action(text,text,jsonb) to anon;
grant execute on function public.typing_foundation_action(text,text,jsonb) to authenticated;
grant execute on function public.typing_foundation_action(text,text,jsonb) to service_role;

-- upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean)  md5=fa0e675b4a739c40f5103faa72edfd3e
CREATE OR REPLACE FUNCTION public.upsert_guest_progress(p_course_id text, p_week_code text, p_activity_key text, p_class_code text, p_seat_no smallint, p_birthday_code text, p_current_level integer, p_score smallint, p_completed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
    v_student record;
    v_score smallint;
    v_current_level integer;
begin
    if p_week_code !~ '^\d{2}$' then
        raise exception 'invalid week_code';
    end if;

    if p_activity_key !~ '^[a-z0-9_:-]{3,64}$' then
        raise exception 'invalid activity_key';
    end if;

    select * into v_student
    from public.class_card_students s
    where s.course_id = p_course_id
      and s.class_code = p_class_code
      and s.seat_no = p_seat_no
      and s.birthday_code = p_birthday_code
      and s.active = true
    limit 1;

    if v_student is null then
        raise exception 'class card not found';
    end if;

    v_score := greatest(0, least(coalesce(p_score, 0), 20));
    v_current_level := greatest(1, least(coalesce(p_current_level, 1), 20));

    insert into public.guest_progress (
        course_id,
        week_code,
        activity_key,
        student_code,
        class_code,
        seat_no,
        display_name,
        current_level,
        score,
        completed,
        updated_at
    ) values (
        v_student.course_id,
        p_week_code,
        p_activity_key,
        v_student.student_code,
        v_student.class_code,
        v_student.seat_no,
        v_student.display_name,
        v_current_level,
        v_score,
        coalesce(p_completed, false),
        now()
    )
    on conflict (course_id, week_code, activity_key, student_code)
    do update set
        class_code = excluded.class_code,
        seat_no = excluded.seat_no,
        display_name = excluded.display_name,
        current_level = excluded.current_level,
        score = excluded.score,
        completed = excluded.completed,
        updated_at = now();
end;
$function$;
revoke all on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) from public, anon, authenticated, service_role;
grant execute on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) to public;
grant execute on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) to postgres;
grant execute on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) to anon;
grant execute on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) to authenticated;
grant execute on function public.upsert_guest_progress(text,text,text,text,smallint,text,integer,smallint,boolean) to service_role;

-- verify_class_card_identity(text,text,smallint,text)  md5=ee499906b34a768abe85439a46623e47
CREATE OR REPLACE FUNCTION public.verify_class_card_identity(p_course_id text, p_class_code text, p_seat_no smallint, p_birthday_code text)
 RETURNS TABLE(course_id text, class_code text, seat_no smallint, student_code text, display_name text, profile_id text)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select s.course_id,s.class_code,s.seat_no,s.student_code,s.display_name,
 s.course_id || ':' || s.class_code || ':' || lpad(s.seat_no::text,2,'0')
 from public.class_card_students s where s.course_id=p_course_id and s.course_id<>'grade3-115-1'
 and s.class_code=p_class_code and s.seat_no=p_seat_no and s.birthday_code=p_birthday_code and s.active limit 1;
$function$;
revoke all on function public.verify_class_card_identity(text,text,smallint,text) from public, anon, authenticated, service_role;
grant execute on function public.verify_class_card_identity(text,text,smallint,text) to postgres;
grant execute on function public.verify_class_card_identity(text,text,smallint,text) to service_role;
grant execute on function public.verify_class_card_identity(text,text,smallint,text) to anon;
grant execute on function public.verify_class_card_identity(text,text,smallint,text) to authenticated;
